const BOOK={"id":"science-4-part-1","grade":4,"gradeLabel":"الصف الرابع","mediaPrefix":"g4-","title":"العلوم للصف الرابع · الجزء الأول","source":"https://www.edunet.bh/e_content/level_1/stage_4/subject_ID_5/Part_1/e_books/SCGr4SB/SCGr4SB/files/SCGr4SB2026.pdf","units":[{"id":"living","title":"تصنيف المخلوقات الحية","lessons":[{"id":"cells","title":"الخلايا","start":12,"end":19,"terms":["cell","unicellular","multicellular","chloroplast","plant-cell","animal-cell","cell-wall","cell-membrane","cell-nucleus","cytoplasm","vacuole","tissue","organ","organ-system","red-blood-cell","nerve-cell","muscle-cell"]},{"id":"kingdoms","title":"ممالك المخلوقات الحية","start":20,"end":28,"terms":["classification","kingdom","plants","animals","fungi","protists","bacteria","archaea","trait","microscope","algae","red-tide"]}]},{"id":"plant-animal","title":"المملكة النباتية والمملكة الحيوانية","lessons":[{"id":"plants4","title":"المملكة النباتية","start":32,"end":41,"terms":["vascular","nonvascular","seed-plants","seedless","photosynthesis","stomata","transpiration","root","stem","leaf","chlorophyll","leaf-vein","seed","fruit","spore","moss","fern","plant-epidermis","carbon-dioxide","oxygen","glucose"]},{"id":"animals4","title":"المملكة الحيوانية","start":42,"end":54,"terms":["vertebrates","invertebrates","sponges","echinoderms","cnidarians","molluscs","arthropods","flatworms","roundworms","annelids","fish","amphibians","reptiles","birds","mammals","backbone","endoskeleton","insects","arachnids","crustaceans","myriapods","warm-blooded","cold-blooded","bony-fish","cartilaginous-fish","jawless-fish","gills","scales"]}]},{"id":"matter4","title":"المادة وتغيراتها","lessons":[{"id":"properties","title":"وصف المادة","start":58,"end":65,"terms":["matter","solid","liquid","gas","property","mass","volume","solubility","dissolving","cubic-meter","graduated-beaker","magnetism","buoyancy","balance","graduated-cylinder","gram","kilogram","cubic-centimeter","reusing","recycling"]},{"id":"changes4","title":"تغيرات المادة","start":66,"end":76,"terms":["physical-change","chemical-change","melting","evaporation","condensation","freezing","thermal-expansion","thermal-contraction","rust","heating","cooling","water-vapour","combustion"]}]},{"id":"space","title":"الفضاء","lessons":[{"id":"earth-moon","title":"الأرض والشمس والقمر","start":80,"end":91,"terms":["earth","sun","moon","rotation","revolution","axis","orbit","equator","north-pole","south-pole","day-night","shadow","apparent-motion","seasons","lunar-crater","moon-phases","new-moon","crescent","first-quarter","gibbous","full-moon","last-quarter","gravity","tides","lunar-eclipse","solar-eclipse","atmosphere"]},{"id":"solar","title":"النظام الشمسي والنجوم والبروج السماوية","start":92,"end":102,"terms":["satellite","artificial-satellite","solar-system","planet","rocky-planets","giant-planets","mercury","venus","mars","jupiter","saturn","uranus","neptune","comet","asteroid","asteroid-belt","meteor","meteorite","star","galaxy","milky-way","constellation"]}]},{"id":"health","title":"عمليات الحياة في الإنسان وغذاؤه الصحي","lessons":[{"id":"systems","title":"الهضم والإخراج والتنفس والدوران","start":106,"end":113,"terms":["digestion","digestive-system","mouth","saliva","oesophagus","stomach","liver","pancreas","small-intestine","large-intestine","excretion","urinary-system","kidneys","nephron","ureter","bladder","urethra","breathing","respiratory-system","pharynx","larynx","trachea","bronchi","bronchioles","alveoli","lungs","diaphragm","circulation","circulatory-system","heart","atrium","ventricle","artery","vein","capillary","oxygenated-blood","deoxygenated-blood","respiration"]},{"id":"nutrition","title":"الغذاء والصحة والمرض","start":114,"end":124,"terms":["nutrient","carbohydrate","starch-food","sugar-food","vitamin","vitamin-a","vitamin-c","vitamin-d","mineral","calcium","iron-nutrient","fat","protein","water-nutrient","balanced-diet","immune-system","pathogen","virus-health","bacteria-health","prevention","vaccine"]}]}],"terms":[{"id":"cell","name":"الخلية","meaning":"وحدة بناء المخلوق الحي، وتقوم بعمليات الحياة.","example":"تتكون البكتيريا من خلية واحدة.","page":14,"aliases":[],"visualId":"cell","unit":"living","lesson":"cells","audioText":"الخلية. وحدة بناء المخلوق الحي، وتقوم بعمليات الحياة. مثال. تتكون البكتيريا من خلية واحدة.","imageQuiz":false},{"id":"unicellular","name":"وحيد الخلية","meaning":"مخلوق حي يتكون جسمه من خلية واحدة.","example":"الأميبا مخلوق وحيد الخلية.","page":14,"aliases":["وحيدة الخلية"],"visualId":"unicellular","unit":"living","lesson":"cells","audioText":"وحيد الخلية. مخلوق حي يتكون جسمه من خلية واحدة. مثال. الأميبا مخلوق وحيد الخلية.","imageQuiz":false},{"id":"multicellular","name":"متعدد الخلايا","meaning":"مخلوق حي يتكون جسمه من خلايا كثيرة.","example":"الحصان مخلوق متعدد الخلايا.","page":14,"aliases":["متعددة الخلايا"],"visualId":"multicellular","unit":"living","lesson":"cells","audioText":"متعدد الخلايا. مخلوق حي يتكون جسمه من خلايا كثيرة. مثال. الحصان مخلوق متعدد الخلايا.","imageQuiz":false},{"id":"chloroplast","name":"البلاستيدات الخضراء","meaning":"تراكيب في الخلايا النباتية تحتوي الكلوروفيل ويحدث فيها البناء الضوئي.","example":"تصنع الخلية السكر داخل البلاستيدات الخضراء.","page":14,"aliases":[],"visualId":"chloroplast","unit":"living","lesson":"cells","audioText":"البلاستيدات الخضراء. تراكيب في الخلايا النباتية تحتوي الكلوروفيل ويحدث فيها البناء الضوئي. مثال. تصنع الخلية السكر داخل البلاستيدات الخضراء.","imageQuiz":true},{"id":"plant-cell","name":"الخلية النباتية","meaning":"وحدة بناء النبات، لها جدار خلوي، وتحتوي خلايا الأوراق عادة على بلاستيدات خضراء.","example":"خلايا ورقة النبات تصنع الغذاء.","page":14,"aliases":[],"visualId":"plant-cell","unit":"living","lesson":"cells","audioText":"الخلية النباتية. وحدة بناء النبات، لها جدار خلوي، وتحتوي خلايا الأوراق عادة على بلاستيدات خضراء. مثال. خلايا ورقة النبات تصنع الغذاء.","imageQuiz":true},{"id":"animal-cell","name":"الخلية الحيوانية","meaning":"وحدة بناء الحيوان، لها غشاء خلوي ولا يحيط بها جدار خلوي.","example":"يتكون جسم القطة من خلايا حيوانية.","page":15,"aliases":[],"visualId":"animal-cell","unit":"living","lesson":"cells","audioText":"الخلية الحيوانية. وحدة بناء الحيوان، لها غشاء خلوي ولا يحيط بها جدار خلوي. مثال. يتكون جسم القطة من خلايا حيوانية.","imageQuiz":true},{"id":"cell-wall","name":"الجدار الخلوي","meaning":"غطاء صلب يحيط بالخلية النباتية ويدعمها ويحافظ على شكلها.","example":"يساعد الجدار على ثبات شكل الخلية النباتية.","page":15,"aliases":[],"visualId":"cell-wall","unit":"living","lesson":"cells","audioText":"الجدار الخلوي. غطاء صلب يحيط بالخلية النباتية ويدعمها ويحافظ على شكلها. مثال. يساعد الجدار على ثبات شكل الخلية النباتية.","imageQuiz":true},{"id":"cell-membrane","name":"الغشاء الخلوي","meaning":"غلاف رقيق يحيط بالخلية وينظم دخول المواد وخروجها.","example":"تحصل الخلية على حاجاتها عبر الغشاء.","page":15,"aliases":[],"visualId":"cell-membrane","unit":"living","lesson":"cells","audioText":"الغشاء الخلوي. غلاف رقيق يحيط بالخلية وينظم دخول المواد وخروجها. مثال. تحصل الخلية على حاجاتها عبر الغشاء.","imageQuiz":true},{"id":"cell-nucleus","name":"النواة","meaning":"جزء داخل الخلية يتحكم في كثير من أنشطتها.","example":"توجد النواة داخل الخلية النباتية والحيوانية.","page":15,"aliases":[],"visualId":"cell-nucleus","unit":"living","lesson":"cells","audioText":"النواة. جزء داخل الخلية يتحكم في كثير من أنشطتها. مثال. توجد النواة داخل الخلية النباتية والحيوانية.","imageQuiz":true},{"id":"cytoplasm","name":"السيتوبلازم","meaning":"مادة هلامية داخل الخلية تحيط بأجزائها.","example":"توجد النواة وأجزاء الخلية في السيتوبلازم.","page":15,"aliases":["السيتوبلازم"],"visualId":"cytoplasm","unit":"living","lesson":"cells","audioText":"السيتوبلازم. مادة هلامية داخل الخلية تحيط بأجزائها. مثال. توجد النواة وأجزاء الخلية في السيتوبلازم.","imageQuiz":true},{"id":"vacuole","name":"الفجوة العصارية","meaning":"جزء يخزن الماء ومواد أخرى في الخلية، ويكون كبيرًا غالبًا في الخلية النباتية.","example":"تخزن الفجوة ماءً داخل الخلية.","page":15,"aliases":["الفجوة"],"visualId":"vacuole","unit":"living","lesson":"cells","audioText":"الفجوة العصارية. جزء يخزن الماء ومواد أخرى في الخلية، ويكون كبيرًا غالبًا في الخلية النباتية. مثال. تخزن الفجوة ماءً داخل الخلية.","imageQuiz":true},{"id":"tissue","name":"النسيج","meaning":"مجموعة خلايا متشابهة تتعاون لأداء وظيفة.","example":"الخلايا العضلية تكوّن نسيجًا عضليًا.","page":17,"aliases":[],"visualId":"tissue","unit":"living","lesson":"cells","audioText":"النسيج. مجموعة خلايا متشابهة تتعاون لأداء وظيفة. مثال. الخلايا العضلية تكوّن نسيجًا عضليًا.","imageQuiz":true},{"id":"organ","name":"العضو","meaning":"جزء مكوّن من أنسجة مختلفة يعمل لأداء وظيفة محددة.","example":"القلب عضو يضخ الدم.","page":17,"aliases":[],"visualId":"organ","unit":"living","lesson":"cells","audioText":"العضو. جزء مكوّن من أنسجة مختلفة يعمل لأداء وظيفة محددة. مثال. القلب عضو يضخ الدم.","imageQuiz":true},{"id":"organ-system","name":"الجهاز","meaning":"مجموعة أعضاء تعمل معًا لأداء وظائف مترابطة.","example":"القلب والأوعية الدموية أجزاء من جهاز الدوران.","page":17,"aliases":["الجهاز الحيوي","جهاز الجسم"],"visualId":"organ-system","unit":"living","lesson":"cells","audioText":"الجهاز. مجموعة أعضاء تعمل معًا لأداء وظائف مترابطة. مثال. القلب والأوعية الدموية أجزاء من جهاز الدوران.","imageQuiz":true},{"id":"red-blood-cell","name":"خلايا الدم الحمراء","meaning":"خلايا في الدم تنقل الأكسجين إلى أجزاء الجسم.","example":"تحمل خلايا الدم الحمراء الأكسجين إلى العضلات.","page":16,"aliases":["كريات الدم الحمراء"],"visualId":"red-blood-cell","unit":"living","lesson":"cells","audioText":"خلايا الدم الحمراء. خلايا في الدم تنقل الأكسجين إلى أجزاء الجسم. مثال. تحمل خلايا الدم الحمراء الأكسجين إلى العضلات.","imageQuiz":true},{"id":"nerve-cell","name":"الخلية العصبية","meaning":"خلية تنقل إشارات ومعلومات بين أجزاء الجسم.","example":"تنقل الخلايا العصبية إشارات تساعد على الحركة.","page":16,"aliases":["الخلايا العصبية"],"visualId":"nerve-cell","unit":"living","lesson":"cells","audioText":"الخلية العصبية. خلية تنقل إشارات ومعلومات بين أجزاء الجسم. مثال. تنقل الخلايا العصبية إشارات تساعد على الحركة.","imageQuiz":true},{"id":"muscle-cell","name":"الخلية العضلية","meaning":"خلية تستطيع الانقباض وتساعد على الحركة.","example":"تتعاون الخلايا العضلية لتحريك الذراع.","page":16,"aliases":["الخلايا العضلية"],"visualId":"muscle-cell","unit":"living","lesson":"cells","audioText":"الخلية العضلية. خلية تستطيع الانقباض وتساعد على الحركة. مثال. تتعاون الخلايا العضلية لتحريك الذراع.","imageQuiz":true},{"id":"classification","name":"التصنيف","meaning":"وضع المخلوقات الحية في مجموعات حسب صفاتها المشتركة.","example":"نجمع القطط في مجموعة تختلف عن مجموعة النباتات.","page":22,"aliases":[],"visualId":"classification","unit":"living","lesson":"kingdoms","audioText":"التصنيف. وضع المخلوقات الحية في مجموعات حسب صفاتها المشتركة. مثال. نجمع القطط في مجموعة تختلف عن مجموعة النباتات.","imageQuiz":false},{"id":"kingdom","name":"المملكة","meaning":"أوسع مستوى في التصنيف الذي يعرضه الدرس، وتضم مجموعات كثيرة.","example":"مملكة الحيوانات تضم الحصان والفراشة.","page":23,"aliases":[],"visualId":"kingdom","unit":"living","lesson":"kingdoms","audioText":"المملكة. أوسع مستوى في التصنيف الذي يعرضه الدرس، وتضم مجموعات كثيرة. مثال. مملكة الحيوانات تضم الحصان والفراشة.","imageQuiz":false},{"id":"plants","name":"النباتات","meaning":"مخلوقات تصنع غذاءها باستخدام ضوء الشمس.","example":"نبات الفاصولياء يصنع غذاءه في أوراقه.","page":23,"aliases":[],"visualId":"plants","unit":"living","lesson":"kingdoms","audioText":"النباتات. مخلوقات تصنع غذاءها باستخدام ضوء الشمس. مثال. نبات الفاصولياء يصنع غذاءه في أوراقه.","imageQuiz":false},{"id":"animals","name":"الحيوانات","meaning":"مخلوقات تحصل على غذائها من مخلوقات أخرى.","example":"الحصان يأكل النباتات.","page":23,"aliases":[],"visualId":"animals","unit":"living","lesson":"kingdoms","audioText":"الحيوانات. مخلوقات تحصل على غذائها من مخلوقات أخرى. مثال. الحصان يأكل النباتات.","imageQuiz":false},{"id":"fungi","name":"الفطريات","meaning":"مخلوقات لا تصنع غذاءها بنفسها، وتمتص الغذاء من محيطها.","example":"عيش الغراب من الفطريات.","page":25,"aliases":[],"visualId":"fungi","unit":"living","lesson":"kingdoms","audioText":"الفطريات. مخلوقات لا تصنع غذاءها بنفسها، وتمتص الغذاء من محيطها. مثال. عيش الغراب من الفطريات.","imageQuiz":true},{"id":"protists","name":"الطلائعيات","meaning":"مجموعة متنوعة؛ معظمها وحيد الخلية، وبعضها يصنع غذاءه وبعضها لا يصنعه.","example":"الأميبا من الطلائعيات.","page":25,"aliases":[],"visualId":"protists","unit":"living","lesson":"kingdoms","audioText":"الطلائعيات. مجموعة متنوعة؛ معظمها وحيد الخلية، وبعضها يصنع غذاءه وبعضها لا يصنعه. مثال. الأميبا من الطلائعيات.","imageQuiz":false},{"id":"bacteria","name":"البكتيريا","meaning":"مخلوقات مجهرية وحيدة الخلية، منها النافع ومنها الضار.","example":"بعض البكتيريا تساعد أجسامنا على الهضم.","page":24,"aliases":[],"visualId":"bacteria","unit":"living","lesson":"kingdoms","audioText":"البكتيريا. مخلوقات مجهرية وحيدة الخلية، منها النافع ومنها الضار. مثال. بعض البكتيريا تساعد أجسامنا على الهضم.","imageQuiz":true},{"id":"archaea","name":"البكتيريا البدائية","meaning":"مخلوقات مجهرية وحيدة الخلية، يعيش بعضها في ظروف قاسية.","example":"يعيش بعض أفرادها في المياه الحارة.","page":24,"aliases":[],"visualId":"archaea","unit":"living","lesson":"kingdoms","audioText":"البكتيريا البدائية. مخلوقات مجهرية وحيدة الخلية، يعيش بعضها في ظروف قاسية. مثال. يعيش بعض أفرادها في المياه الحارة.","imageQuiz":false},{"id":"trait","name":"الصفة","meaning":"خاصية من خصائص المخلوق الحي يمكن استخدامها في المقارنة والتصنيف.","example":"عدد الخلايا وطريقة الحصول على الغذاء من الصفات.","page":22,"aliases":[],"visualId":"trait","unit":"living","lesson":"kingdoms","audioText":"الصفة. خاصية من خصائص المخلوق الحي يمكن استخدامها في المقارنة والتصنيف. مثال. عدد الخلايا وطريقة الحصول على الغذاء من الصفات.","imageQuiz":false},{"id":"microscope","name":"المجهر","meaning":"أداة تكبّر الأشياء الدقيقة التي يصعب رؤيتها بالعين وحدها.","example":"نستخدم المجهر لرؤية الخلايا.","page":24,"aliases":[],"visualId":"microscope","unit":"living","lesson":"kingdoms","audioText":"المجهر. أداة تكبّر الأشياء الدقيقة التي يصعب رؤيتها بالعين وحدها. مثال. نستخدم المجهر لرؤية الخلايا.","imageQuiz":true},{"id":"algae","name":"الطحالب","meaning":"مخلوقات يعيش كثير منها في الماء، ويصنع كثير منها غذاءه بالضوء.","example":"قد نرى طحالب خضراء في الماء.","page":25,"aliases":[],"visualId":"algae","unit":"living","lesson":"kingdoms","audioText":"الطحالب. مخلوقات يعيش كثير منها في الماء، ويصنع كثير منها غذاءه بالضوء. مثال. قد نرى طحالب خضراء في الماء.","imageQuiz":false},{"id":"red-tide","name":"المد الأحمر","meaning":"زيادة كبيرة لبعض العوالق المائية قد تغير لون الماء وتؤذي مخلوقات البحر.","example":"يدرس العلماء تغير لون الماء عند المد الأحمر.","page":27,"aliases":[],"visualId":"red-tide","unit":"living","lesson":"kingdoms","audioText":"المد الأحمر. زيادة كبيرة لبعض العوالق المائية قد تغير لون الماء وتؤذي مخلوقات البحر. مثال. يدرس العلماء تغير لون الماء عند المد الأحمر.","imageQuiz":true},{"id":"vascular","name":"النباتات الوعائية","meaning":"نباتات فيها أنسجة تنقل الماء والغذاء بين أجزائها.","example":"الفاصولياء نبات وعائي.","page":34,"aliases":[],"visualId":"vascular","unit":"plant-animal","lesson":"plants4","audioText":"النباتات الوعائية. نباتات فيها أنسجة تنقل الماء والغذاء بين أجزائها. مثال. الفاصولياء نبات وعائي.","imageQuiz":false},{"id":"nonvascular","name":"النباتات اللاوعائية","meaning":"نباتات ليس فيها أنسجة وعائية متخصصة لنقل الماء والغذاء.","example":"الحزازيات نباتات لاوعائية.","page":34,"aliases":[],"visualId":"nonvascular","unit":"plant-animal","lesson":"plants4","audioText":"النباتات اللاوعائية. نباتات ليس فيها أنسجة وعائية متخصصة لنقل الماء والغذاء. مثال. الحزازيات نباتات لاوعائية.","imageQuiz":false},{"id":"seed-plants","name":"النباتات البذرية","meaning":"نباتات تنتج بذورًا يمكن أن تنمو إلى نباتات جديدة.","example":"الصنوبر والقرع نباتات بذرية.","page":35,"aliases":[],"visualId":"seed-plants","unit":"plant-animal","lesson":"plants4","audioText":"النباتات البذرية. نباتات تنتج بذورًا يمكن أن تنمو إلى نباتات جديدة. مثال. الصنوبر والقرع نباتات بذرية.","imageQuiz":false},{"id":"seedless","name":"النباتات اللابذرية","meaning":"نباتات لا تنتج بذورًا، ويتكاثر كثير منها بالأبواغ.","example":"السرخس مثال لنبات لابذري.","page":35,"aliases":[],"visualId":"seedless","unit":"plant-animal","lesson":"plants4","audioText":"النباتات اللابذرية. نباتات لا تنتج بذورًا، ويتكاثر كثير منها بالأبواغ. مثال. السرخس مثال لنبات لابذري.","imageQuiz":false},{"id":"photosynthesis","name":"البناء الضوئي","meaning":"عملية يصنع فيها النبات السكر من الماء وثاني أكسيد الكربون باستخدام الضوء، وينتج عنها الأكسجين.","example":"تستخدم الورقة ضوء الشمس لصنع الغذاء.","page":38,"aliases":[],"visualId":"photosynthesis","unit":"plant-animal","lesson":"plants4","audioText":"البناء الضوئي. عملية يصنع فيها النبات السكر من الماء وثاني أكسيد الكربون باستخدام الضوء، وينتج عنها الأكسجين. مثال. تستخدم الورقة ضوء الشمس لصنع الغذاء.","imageQuiz":true},{"id":"stomata","name":"الثغور","meaning":"فتحات صغيرة في الورقة تمر عبرها الغازات وبخار الماء.","example":"يدخل ثاني أكسيد الكربون عبر الثغور.","page":39,"aliases":[],"visualId":"stomata","unit":"plant-animal","lesson":"plants4","audioText":"الثغور. فتحات صغيرة في الورقة تمر عبرها الغازات وبخار الماء. مثال. يدخل ثاني أكسيد الكربون عبر الثغور.","imageQuiz":true},{"id":"transpiration","name":"النتح","meaning":"خروج الماء من النبات على هيئة بخار، ويحدث معظمه عبر ثغور الأوراق.","example":"تفقد الورقة بعض الماء بعملية النتح.","page":39,"aliases":[],"visualId":"transpiration","unit":"plant-animal","lesson":"plants4","audioText":"النتح. خروج الماء من النبات على هيئة بخار، ويحدث معظمه عبر ثغور الأوراق. مثال. تفقد الورقة بعض الماء بعملية النتح.","imageQuiz":true},{"id":"root","name":"الجذر","meaning":"جزء يثبت النبات ويمتص الماء والأملاح من التربة.","example":"يمتص جذر الجزر الماء من التربة.","page":39,"aliases":[],"visualId":"root","unit":"plant-animal","lesson":"plants4","audioText":"الجذر. جزء يثبت النبات ويمتص الماء والأملاح من التربة. مثال. يمتص جذر الجزر الماء من التربة.","imageQuiz":true},{"id":"stem","name":"الساق","meaning":"جزء يدعم النبات ويحمل الأوراق، وتنقل أنسجته الماء والغذاء.","example":"ترفع الساق الأوراق نحو الضوء.","page":39,"aliases":[],"visualId":"stem","unit":"plant-animal","lesson":"plants4","audioText":"الساق. جزء يدعم النبات ويحمل الأوراق، وتنقل أنسجته الماء والغذاء. مثال. ترفع الساق الأوراق نحو الضوء.","imageQuiz":true},{"id":"leaf","name":"الورقة","meaning":"جزء يصنع معظم غذاء النبات باستخدام الضوء.","example":"تستقبل الورقة ضوء الشمس.","page":38,"aliases":[],"visualId":"leaf","unit":"plant-animal","lesson":"plants4","audioText":"الورقة. جزء يصنع معظم غذاء النبات باستخدام الضوء. مثال. تستقبل الورقة ضوء الشمس.","imageQuiz":true},{"id":"chlorophyll","name":"الكلوروفيل","meaning":"صبغة خضراء تمتص طاقة الضوء اللازمة للبناء الضوئي.","example":"يعطي الكلوروفيل الأوراق لونها الأخضر.","page":38,"aliases":[],"visualId":"chlorophyll","unit":"plant-animal","lesson":"plants4","audioText":"الكلوروفيل. صبغة خضراء تمتص طاقة الضوء اللازمة للبناء الضوئي. مثال. يعطي الكلوروفيل الأوراق لونها الأخضر.","imageQuiz":true},{"id":"leaf-vein","name":"عِرق الورقة","meaning":"تركيب داخل الورقة يضم أنسجة نقل الماء والغذاء.","example":"تتفرع العروق في نصل الورقة.","page":39,"aliases":["عروق الورقة","العرق"],"visualId":"leaf-vein","unit":"plant-animal","lesson":"plants4","audioText":"عِرق الورقة. تركيب داخل الورقة يضم أنسجة نقل الماء والغذاء. مثال. تتفرع العروق في نصل الورقة.","imageQuiz":true},{"id":"seed","name":"البذرة","meaning":"تركيب يضم جنين نبات ومخزونًا غذائيًا وغلافًا يحميه.","example":"تنمو البذرة إلى نبتة عند توفر الظروف المناسبة.","page":35,"aliases":[],"visualId":"seed","unit":"plant-animal","lesson":"plants4","audioText":"البذرة. تركيب يضم جنين نبات ومخزونًا غذائيًا وغلافًا يحميه. مثال. تنمو البذرة إلى نبتة عند توفر الظروف المناسبة.","imageQuiz":true},{"id":"fruit","name":"الثمرة","meaning":"جزء ينشأ غالبًا من مبيض الزهرة ويحتوي البذور ويحميها.","example":"داخل ثمرة القرع بذور.","page":40,"aliases":[],"visualId":"fruit","unit":"plant-animal","lesson":"plants4","audioText":"الثمرة. جزء ينشأ غالبًا من مبيض الزهرة ويحتوي البذور ويحميها. مثال. داخل ثمرة القرع بذور.","imageQuiz":true},{"id":"spore","name":"البوغ","meaning":"خلية تكاثر تستطيع أن تنمو إلى مخلوق جديد، ومنها أبواغ النباتات اللابذرية.","example":"تنتج السرخسيات أبواغًا على أسفل أوراقها.","page":36,"aliases":["الأبواغ"],"visualId":"spore","unit":"plant-animal","lesson":"plants4","audioText":"البوغ. خلية تكاثر تستطيع أن تنمو إلى مخلوق جديد، ومنها أبواغ النباتات اللابذرية. مثال. تنتج السرخسيات أبواغًا على أسفل أوراقها.","imageQuiz":true},{"id":"moss","name":"الحزازيات","meaning":"نباتات لابذرية صغيرة ليس لها أوعية ناقلة أو جذور حقيقية.","example":"تنمو الحزازيات قريبة من التربة الرطبة.","page":36,"aliases":[],"visualId":"moss","unit":"plant-animal","lesson":"plants4","audioText":"الحزازيات. نباتات لابذرية صغيرة ليس لها أوعية ناقلة أو جذور حقيقية. مثال. تنمو الحزازيات قريبة من التربة الرطبة.","imageQuiz":true},{"id":"fern","name":"السرخسيات","meaning":"نباتات لابذرية لها جذور وسيقان وأوراق وأوعية ناقلة، وتتكاثر بالأبواغ.","example":"توجد أبواغ تحت أوراق السرخس.","page":36,"aliases":[],"visualId":"fern","unit":"plant-animal","lesson":"plants4","audioText":"السرخسيات. نباتات لابذرية لها جذور وسيقان وأوراق وأوعية ناقلة، وتتكاثر بالأبواغ. مثال. توجد أبواغ تحت أوراق السرخس.","imageQuiz":true},{"id":"plant-epidermis","name":"البشرة","meaning":"طبقة تغطي سطح الورقة وتحمي أجزاءها الداخلية.","example":"تحمي بشرة الورقة أنسجتها.","page":39,"aliases":[],"visualId":"waxy-layer","unit":"plant-animal","lesson":"plants4","audioText":"البشرة. طبقة تغطي سطح الورقة وتحمي أجزاءها الداخلية. مثال. تحمي بشرة الورقة أنسجتها.","imageQuiz":true},{"id":"carbon-dioxide","name":"ثاني أكسيد الكربون","meaning":"غاز تستعمله النباتات مع الماء والضوء لصنع الغذاء.","example":"يدخل ثاني أكسيد الكربون إلى الورقة عبر الثغور.","page":38,"aliases":[],"visualId":"carbon-dioxide","unit":"plant-animal","lesson":"plants4","audioText":"ثاني أكسيد الكربون. غاز تستعمله النباتات مع الماء والضوء لصنع الغذاء. مثال. يدخل ثاني أكسيد الكربون إلى الورقة عبر الثغور.","imageQuiz":true},{"id":"oxygen","name":"الأكسجين","meaning":"غاز تحتاج إليه معظم المخلوقات لإطلاق الطاقة من الغذاء، وتنتجه النباتات في البناء الضوئي.","example":"تطلق الورقة الأكسجين أثناء البناء الضوئي.","page":38,"aliases":[],"visualId":"oxygen","unit":"plant-animal","lesson":"plants4","audioText":"الأكسجين. غاز تحتاج إليه معظم المخلوقات لإطلاق الطاقة من الغذاء، وتنتجه النباتات في البناء الضوئي. مثال. تطلق الورقة الأكسجين أثناء البناء الضوئي.","imageQuiz":true},{"id":"glucose","name":"الجلوكوز","meaning":"سكر تصنعه النباتات في البناء الضوئي وتستفيد منه الخلايا في الحصول على الطاقة.","example":"تصنع الورقة سكر الجلوكوز.","page":39,"aliases":["سكر الجلوكوز"],"visualId":"glucose","unit":"plant-animal","lesson":"plants4","audioText":"الجلوكوز. سكر تصنعه النباتات في البناء الضوئي وتستفيد منه الخلايا في الحصول على الطاقة. مثال. تصنع الورقة سكر الجلوكوز.","imageQuiz":true},{"id":"vertebrates","name":"الفقاريات","meaning":"حيوانات لها عمود فقري.","example":"الحصان من الفقاريات.","page":44,"aliases":[],"visualId":"vertebrates","unit":"plant-animal","lesson":"animals4","audioText":"الفقاريات. حيوانات لها عمود فقري. مثال. الحصان من الفقاريات.","imageQuiz":false},{"id":"invertebrates","name":"اللافقاريات","meaning":"حيوانات ليس لها عمود فقري.","example":"الفراشة ودودة الأرض من اللافقاريات.","page":44,"aliases":[],"visualId":"invertebrates","unit":"plant-animal","lesson":"animals4","audioText":"اللافقاريات. حيوانات ليس لها عمود فقري. مثال. الفراشة ودودة الأرض من اللافقاريات.","imageQuiz":false},{"id":"sponges","name":"الإسفنجيات","meaning":"حيوانات مائية لا فقارية، تحتوي أجسامها على ثقوب يمر خلالها الماء.","example":"الإسفنج من الحيوانات اللافقارية.","page":44,"aliases":[],"visualId":"sponges","unit":"plant-animal","lesson":"animals4","audioText":"الإسفنجيات. حيوانات مائية لا فقارية، تحتوي أجسامها على ثقوب يمر خلالها الماء. مثال. الإسفنج من الحيوانات اللافقارية.","imageQuiz":true},{"id":"echinoderms","name":"شوكيات الجلد","meaning":"حيوانات بحرية لا فقارية، لها تراكيب شوكية في الجلد أو تحته.","example":"نجم البحر من شوكيات الجلد.","page":45,"aliases":[],"visualId":"echinoderms","unit":"plant-animal","lesson":"animals4","audioText":"شوكيات الجلد. حيوانات بحرية لا فقارية، لها تراكيب شوكية في الجلد أو تحته. مثال. نجم البحر من شوكيات الجلد.","imageQuiz":true},{"id":"cnidarians","name":"اللاسعات","meaning":"حيوانات لا فقارية تمتلك خلايا لاسعة تساعدها على الحصول على الغذاء.","example":"قنديل البحر من اللاسعات.","page":45,"aliases":[],"visualId":"cnidarians","unit":"plant-animal","lesson":"animals4","audioText":"اللاسعات. حيوانات لا فقارية تمتلك خلايا لاسعة تساعدها على الحصول على الغذاء. مثال. قنديل البحر من اللاسعات.","imageQuiz":true},{"id":"molluscs","name":"الرخويات","meaning":"حيوانات لا فقارية رخوة الجسم، لبعضها أصداف.","example":"الحلزون من الرخويات.","page":46,"aliases":[],"visualId":"molluscs","unit":"plant-animal","lesson":"animals4","audioText":"الرخويات. حيوانات لا فقارية رخوة الجسم، لبعضها أصداف. مثال. الحلزون من الرخويات.","imageQuiz":true},{"id":"arthropods","name":"المفصليات","meaning":"حيوانات لا فقارية لها أرجل مفصلية وهيكل خارجي.","example":"اليعسوب من المفصليات.","page":46,"aliases":[],"visualId":"arthropods","unit":"plant-animal","lesson":"animals4","audioText":"المفصليات. حيوانات لا فقارية لها أرجل مفصلية وهيكل خارجي. مثال. اليعسوب من المفصليات.","imageQuiz":false},{"id":"flatworms","name":"الديدان المفلطحة","meaning":"ديدان لا فقارية أجسامها مسطحة.","example":"الدودة الشريطية من الديدان المفلطحة.","page":47,"aliases":[],"visualId":"flatworms","unit":"plant-animal","lesson":"animals4","audioText":"الديدان المفلطحة. ديدان لا فقارية أجسامها مسطحة. مثال. الدودة الشريطية من الديدان المفلطحة.","imageQuiz":true},{"id":"roundworms","name":"الديدان الأسطوانية","meaning":"ديدان لا فقارية أجسامها أسطوانية غير مقسمة إلى حلقات.","example":"دودة الإسكارس من الديدان الأسطوانية.","page":47,"aliases":[],"visualId":"roundworms","unit":"plant-animal","lesson":"animals4","audioText":"الديدان الأسطوانية. ديدان لا فقارية أجسامها أسطوانية غير مقسمة إلى حلقات. مثال. دودة الإسكارس من الديدان الأسطوانية.","imageQuiz":true},{"id":"annelids","name":"الديدان الحلقية","meaning":"ديدان لا فقارية أجسامها مقسمة إلى حلقات.","example":"دودة الأرض من الديدان الحلقية.","page":47,"aliases":[],"visualId":"annelids","unit":"plant-animal","lesson":"animals4","audioText":"الديدان الحلقية. ديدان لا فقارية أجسامها مقسمة إلى حلقات. مثال. دودة الأرض من الديدان الحلقية.","imageQuiz":true},{"id":"fish","name":"الأسماك","meaning":"فقاريات مائية تتنفس بالخياشيم ولها زعانف.","example":"تستخدم السمكة زعانفها في الحركة.","page":48,"aliases":[],"visualId":"fish","unit":"plant-animal","lesson":"animals4","audioText":"الأسماك. فقاريات مائية تتنفس بالخياشيم ولها زعانف. مثال. تستخدم السمكة زعانفها في الحركة.","imageQuiz":false},{"id":"amphibians","name":"البرمائيات","meaning":"فقاريات يقضي كثير منها بداية حياته في الماء، ثم يعيش البالغ منها في الماء أو قرب اليابسة.","example":"الضفدع من البرمائيات.","page":49,"aliases":[],"visualId":"amphibians","unit":"plant-animal","lesson":"animals4","audioText":"البرمائيات. فقاريات يقضي كثير منها بداية حياته في الماء، ثم يعيش البالغ منها في الماء أو قرب اليابسة. مثال. الضفدع من البرمائيات.","imageQuiz":true},{"id":"reptiles","name":"الزواحف","meaning":"فقاريات يغطي جسمها جلد جاف ذو حراشف.","example":"التمساح من الزواحف.","page":49,"aliases":[],"visualId":"reptiles","unit":"plant-animal","lesson":"animals4","audioText":"الزواحف. فقاريات يغطي جسمها جلد جاف ذو حراشف. مثال. التمساح من الزواحف.","imageQuiz":true},{"id":"birds","name":"الطيور","meaning":"فقاريات يغطي جسمها الريش ولها مناقير.","example":"الصقر من الطيور.","page":50,"aliases":[],"visualId":"birds","unit":"plant-animal","lesson":"animals4","audioText":"الطيور. فقاريات يغطي جسمها الريش ولها مناقير. مثال. الصقر من الطيور.","imageQuiz":true},{"id":"mammals","name":"الثدييات","meaning":"فقاريات لها شعر أو فرو، وترضع صغارها الحليب.","example":"البقرة من الثدييات.","page":50,"aliases":[],"visualId":"mammals","unit":"plant-animal","lesson":"animals4","audioText":"الثدييات. فقاريات لها شعر أو فرو، وترضع صغارها الحليب. مثال. البقرة من الثدييات.","imageQuiz":true},{"id":"backbone","name":"العمود الفقري","meaning":"سلسلة عظام في ظهر الحيوان الفقاري تدعم الجسم وتحمي الحبل الشوكي.","example":"للسمكة عمود فقري داخل جسمها.","page":48,"aliases":[],"visualId":"backbone","unit":"plant-animal","lesson":"animals4","audioText":"العمود الفقري. سلسلة عظام في ظهر الحيوان الفقاري تدعم الجسم وتحمي الحبل الشوكي. مثال. للسمكة عمود فقري داخل جسمها.","imageQuiz":true},{"id":"endoskeleton","name":"الهيكل الداخلي","meaning":"دعامة داخل جسم الحيوان، تتكون من عظام أو غضاريف.","example":"يدعم الهيكل الداخلي جسم الفرس.","page":48,"aliases":[],"visualId":"endoskeleton","unit":"plant-animal","lesson":"animals4","audioText":"الهيكل الداخلي. دعامة داخل جسم الحيوان، تتكون من عظام أو غضاريف. مثال. يدعم الهيكل الداخلي جسم الفرس.","imageQuiz":true},{"id":"insects","name":"الحشرات","meaning":"مفصليات لها ست أرجل، ويتكون جسمها من ثلاثة أجزاء رئيسة.","example":"الفراشة من الحشرات.","page":46,"aliases":[],"visualId":"insects","unit":"plant-animal","lesson":"animals4","audioText":"الحشرات. مفصليات لها ست أرجل، ويتكون جسمها من ثلاثة أجزاء رئيسة. مثال. الفراشة من الحشرات.","imageQuiz":true},{"id":"arachnids","name":"العنكبيات","meaning":"مفصليات لها ثماني أرجل، ومنها العناكب والعقارب.","example":"العنكبوت من العنكبيات.","page":46,"aliases":[],"visualId":"arachnids","unit":"plant-animal","lesson":"animals4","audioText":"العنكبيات. مفصليات لها ثماني أرجل، ومنها العناكب والعقارب. مثال. العنكبوت من العنكبيات.","imageQuiz":true},{"id":"crustaceans","name":"القشريات","meaning":"مفصليات لها غطاء خارجي صلب، ويعيش كثير منها في الماء.","example":"الروبيان والسرطان من القشريات.","page":46,"aliases":[],"visualId":"crustaceans","unit":"plant-animal","lesson":"animals4","audioText":"القشريات. مفصليات لها غطاء خارجي صلب، ويعيش كثير منها في الماء. مثال. الروبيان والسرطان من القشريات.","imageQuiz":true},{"id":"myriapods","name":"عديدة الأرجل","meaning":"مفصليات أجسامها طويلة مقسمة إلى حلقات تحمل أرجلًا كثيرة.","example":"الحريش من عديدة الأرجل.","page":46,"aliases":[],"visualId":"myriapods","unit":"plant-animal","lesson":"animals4","audioText":"عديدة الأرجل. مفصليات أجسامها طويلة مقسمة إلى حلقات تحمل أرجلًا كثيرة. مثال. الحريش من عديدة الأرجل.","imageQuiz":true},{"id":"warm-blooded","name":"ذوات الدم الحار","meaning":"حيوانات تحافظ على درجة حرارة جسمها مستقرة نسبيًا، مثل الطيور والثدييات.","example":"تبقى حرارة جسم الطائر مستقرة نسبيًا في بيئات مختلفة.","page":48,"aliases":["ثابتة درجة الحرارة"],"visualId":"warm-blooded","unit":"plant-animal","lesson":"animals4","audioText":"ذوات الدم الحار. حيوانات تحافظ على درجة حرارة جسمها مستقرة نسبيًا، مثل الطيور والثدييات. مثال. تبقى حرارة جسم الطائر مستقرة نسبيًا في بيئات مختلفة.","imageQuiz":true},{"id":"cold-blooded","name":"ذوات الدم البارد","meaning":"حيوانات تتأثر درجة حرارة جسمها بحرارة البيئة، مثل الأسماك والزواحف.","example":"تتدفأ السحلية في الشمس.","page":48,"aliases":["متغيرة درجة الحرارة"],"visualId":"cold-blooded","unit":"plant-animal","lesson":"animals4","audioText":"ذوات الدم البارد. حيوانات تتأثر درجة حرارة جسمها بحرارة البيئة، مثل الأسماك والزواحف. مثال. تتدفأ السحلية في الشمس.","imageQuiz":true},{"id":"bony-fish","name":"الأسماك العظمية","meaning":"أسماك يتكون هيكلها الداخلي أساسًا من العظام.","example":"الهامور من الأسماك العظمية.","page":48,"aliases":[],"visualId":"bony-fish","unit":"plant-animal","lesson":"animals4","audioText":"الأسماك العظمية. أسماك يتكون هيكلها الداخلي أساسًا من العظام. مثال. الهامور من الأسماك العظمية.","imageQuiz":true},{"id":"cartilaginous-fish","name":"الأسماك الغضروفية","meaning":"أسماك يتكون هيكلها الداخلي من غضاريف.","example":"القرش من الأسماك الغضروفية.","page":48,"aliases":[],"visualId":"cartilaginous-fish","unit":"plant-animal","lesson":"animals4","audioText":"الأسماك الغضروفية. أسماك يتكون هيكلها الداخلي من غضاريف. مثال. القرش من الأسماك الغضروفية.","imageQuiz":true},{"id":"jawless-fish","name":"الأسماك اللافكية","meaning":"أسماك ليس لها فكّان، ولها فم دائري في أمثلة الدرس.","example":"الجلكي من الأسماك اللافكية.","page":48,"aliases":[],"visualId":"jawless-fish","unit":"plant-animal","lesson":"animals4","audioText":"الأسماك اللافكية. أسماك ليس لها فكّان، ولها فم دائري في أمثلة الدرس. مثال. الجلكي من الأسماك اللافكية.","imageQuiz":true},{"id":"gills","name":"الخياشيم","meaning":"أعضاء تستخلص الأكسجين من الماء عند الأسماك ومخلوقات مائية أخرى.","example":"تتنفس السمكة بالخياشيم.","page":48,"aliases":[],"visualId":"gills","unit":"plant-animal","lesson":"animals4","audioText":"الخياشيم. أعضاء تستخلص الأكسجين من الماء عند الأسماك ومخلوقات مائية أخرى. مثال. تتنفس السمكة بالخياشيم.","imageQuiz":true},{"id":"scales","name":"الحراشف","meaning":"صفائح تغطي جلد كثير من الأسماك والزواحف وتحميه.","example":"تغطي حراشف جافة جلد السحلية.","page":49,"aliases":[],"visualId":"scales","unit":"plant-animal","lesson":"animals4","audioText":"الحراشف. صفائح تغطي جلد كثير من الأسماك والزواحف وتحميه. مثال. تغطي حراشف جافة جلد السحلية.","imageQuiz":true},{"id":"matter","name":"المادة","meaning":"كل ما له كتلة ويشغل حيزًا.","example":"الماء والهواء مواد.","page":60,"aliases":[],"visualId":"matter","unit":"matter4","lesson":"properties","audioText":"المادة. كل ما له كتلة ويشغل حيزًا. مثال. الماء والهواء مواد.","imageQuiz":false},{"id":"solid","name":"الحالة الصلبة","meaning":"حالة تحتفظ فيها المادة بشكل وحجم محددين في الظروف المعتادة.","example":"الجليد مادة صلبة.","page":62,"aliases":[],"visualId":"solid","unit":"matter4","lesson":"properties","audioText":"الحالة الصلبة. حالة تحتفظ فيها المادة بشكل وحجم محددين في الظروف المعتادة. مثال. الجليد مادة صلبة.","imageQuiz":true},{"id":"liquid","name":"الحالة السائلة","meaning":"حالة لها حجم محدد وتأخذ شكل الوعاء.","example":"الماء السائل يأخذ شكل الكأس.","page":62,"aliases":[],"visualId":"liquid","unit":"matter4","lesson":"properties","audioText":"الحالة السائلة. حالة لها حجم محدد وتأخذ شكل الوعاء. مثال. الماء السائل يأخذ شكل الكأس.","imageQuiz":true},{"id":"gas","name":"الحالة الغازية","meaning":"حالة تنتشر فيها المادة لتملأ الحيز المتاح.","example":"ينتشر بخار الماء في الهواء.","page":63,"aliases":[],"visualId":"gas","unit":"matter4","lesson":"properties","audioText":"الحالة الغازية. حالة تنتشر فيها المادة لتملأ الحيز المتاح. مثال. ينتشر بخار الماء في الهواء.","imageQuiz":true},{"id":"property","name":"الخاصية","meaning":"صفة للمادة يمكن ملاحظتها أو قياسها.","example":"اللون والشكل والكتلة من خواص المادة.","page":60,"aliases":["الخصائص","خواص المادة"],"visualId":"property","unit":"matter4","lesson":"properties","audioText":"الخاصية. صفة للمادة يمكن ملاحظتها أو قياسها. مثال. اللون والشكل والكتلة من خواص المادة.","imageQuiz":false},{"id":"mass","name":"الكتلة","meaning":"مقدار ما يحتويه الجسم من مادة.","example":"نقارن كتلتي حجر وريشة بميزان.","page":60,"aliases":[],"visualId":"mass","unit":"matter4","lesson":"properties","audioText":"الكتلة. مقدار ما يحتويه الجسم من مادة. مثال. نقارن كتلتي حجر وريشة بميزان.","imageQuiz":false},{"id":"volume","name":"الحجم","meaning":"مقدار الحيز الذي يشغله الجسم.","example":"يقاس حجم سائل بمخبار مدرج.","page":61,"aliases":[],"visualId":"volume","unit":"matter4","lesson":"properties","audioText":"الحجم. مقدار الحيز الذي يشغله الجسم. مثال. يقاس حجم سائل بمخبار مدرج.","imageQuiz":false},{"id":"solubility","name":"الذائبية","meaning":"قدرة مادة على الذوبان في سائل عند ظروف محددة.","example":"يذوب الملح في الماء، بينما لا يذوب الرمل فيه.","page":61,"aliases":["قابلية الذوبان"],"visualId":"solubility","unit":"matter4","lesson":"properties","audioText":"الذائبية. قدرة مادة على الذوبان في سائل عند ظروف محددة. مثال. يذوب الملح في الماء، بينما لا يذوب الرمل فيه.","imageQuiz":false},{"id":"dissolving","name":"الذوبان","meaning":"انتشار مادة في سائل لتكوين محلول، فلا نميز أجزاء المادة الذائبة بالعين.","example":"يذوب السكر عند تحريكه في الماء.","page":61,"aliases":[],"visualId":"dissolving","unit":"matter4","lesson":"properties","audioText":"الذوبان. انتشار مادة في سائل لتكوين محلول، فلا نميز أجزاء المادة الذائبة بالعين. مثال. يذوب السكر عند تحريكه في الماء.","imageQuiz":true},{"id":"cubic-meter","name":"المتر المكعب","meaning":"وحدة حجم تمثل مكعبًا طول حرفه متر واحد.","example":"حجم صندوق طوله وعرضه وارتفاعه متر واحد يساوي مترًا مكعبًا.","page":61,"aliases":["م٣","م3"],"visualId":"cubic-meter","unit":"matter4","lesson":"properties","audioText":"المتر المكعب. وحدة حجم تمثل مكعبًا طول حرفه متر واحد. مثال. حجم صندوق طوله وعرضه وارتفاعه متر واحد يساوي مترًا مكعبًا.","imageQuiz":true},{"id":"graduated-beaker","name":"الكأس المدرجة","meaning":"وعاء عليه علامات تساعد على تقدير حجم السائل.","example":"يمكن قراءة حجم ماء في كأس مدرجة.","page":61,"aliases":[],"visualId":"graduated-beaker","unit":"matter4","lesson":"properties","audioText":"الكأس المدرجة. وعاء عليه علامات تساعد على تقدير حجم السائل. مثال. يمكن قراءة حجم ماء في كأس مدرجة.","imageQuiz":true},{"id":"magnetism","name":"المغناطيسية","meaning":"قدرة المغناطيس على جذب مواد معينة، ومنها الحديد.","example":"يجذب المغناطيس مشبكًا حديديًا.","page":61,"aliases":[],"visualId":"magnetism","unit":"matter4","lesson":"properties","audioText":"المغناطيسية. قدرة المغناطيس على جذب مواد معينة، ومنها الحديد. مثال. يجذب المغناطيس مشبكًا حديديًا.","imageQuiz":true},{"id":"buoyancy","name":"الطفو","meaning":"قوة دفع السائل أو الغاز للجسم إلى أعلى.","example":"تطفو قطعة خشب فوق الماء.","page":61,"aliases":[],"visualId":"buoyancy","unit":"matter4","lesson":"properties","audioText":"الطفو. قوة دفع السائل أو الغاز للجسم إلى أعلى. مثال. تطفو قطعة خشب فوق الماء.","imageQuiz":true},{"id":"balance","name":"الميزان ذو الكفتين","meaning":"أداة لمقارنة الكتل أو قياسها باستعمال كتل معلومة.","example":"نضع الجسم في كفة وكتلًا معلومة في الكفة الأخرى.","page":60,"aliases":["الميزان"],"visualId":"balance","unit":"matter4","lesson":"properties","audioText":"الميزان ذو الكفتين. أداة لمقارنة الكتل أو قياسها باستعمال كتل معلومة. مثال. نضع الجسم في كفة وكتلًا معلومة في الكفة الأخرى.","imageQuiz":true},{"id":"graduated-cylinder","name":"المخبار المدرج","meaning":"وعاء عليه تدريجات يقاس بها حجم السائل.","example":"نقرأ مستوى الماء في المخبار.","page":61,"aliases":[],"visualId":"graduated-cylinder","unit":"matter4","lesson":"properties","audioText":"المخبار المدرج. وعاء عليه تدريجات يقاس بها حجم السائل. مثال. نقرأ مستوى الماء في المخبار.","imageQuiz":true},{"id":"gram","name":"الجرام","meaning":"وحدة لقياس كتل صغيرة نسبيًا.","example":"يمكن قياس كتلة مشبك بالجرام.","page":60,"aliases":["غرام"],"visualId":"gram","unit":"matter4","lesson":"properties","audioText":"الجرام. وحدة لقياس كتل صغيرة نسبيًا. مثال. يمكن قياس كتلة مشبك بالجرام.","imageQuiz":true},{"id":"kilogram","name":"الكيلوجرام","meaning":"وحدة كتلة تساوي ألف جرام.","example":"نقيس كتلة حقيبة بالكيلوجرام.","page":60,"aliases":["كيلوغرام"],"visualId":"kilogram","unit":"matter4","lesson":"properties","audioText":"الكيلوجرام. وحدة كتلة تساوي ألف جرام. مثال. نقيس كتلة حقيبة بالكيلوجرام.","imageQuiz":true},{"id":"cubic-centimeter","name":"السنتيمتر المكعب","meaning":"وحدة حجم تمثل مكعبًا طول حرفه سنتيمتر واحد.","example":"حجم مكعب صغير يمكن أن يكون سنتيمترًا مكعبًا.","page":61,"aliases":["سم٣","سم3"],"visualId":"cubic-centimeter","unit":"matter4","lesson":"properties","audioText":"السنتيمتر المكعب. وحدة حجم تمثل مكعبًا طول حرفه سنتيمتر واحد. مثال. حجم مكعب صغير يمكن أن يكون سنتيمترًا مكعبًا.","imageQuiz":true},{"id":"reusing","name":"إعادة الاستعمال","meaning":"استخدام الشيء مرة أخرى بدل التخلص منه.","example":"نستعمل علبة فارغة لزراعة البذور.","page":64,"aliases":["إعادة الاستخدام"],"visualId":"reusing","unit":"matter4","lesson":"properties","audioText":"إعادة الاستعمال. استخدام الشيء مرة أخرى بدل التخلص منه. مثال. نستعمل علبة فارغة لزراعة البذور.","imageQuiz":true},{"id":"recycling","name":"التدوير","meaning":"تحويل مخلفات مواد إلى مواد أو منتجات تستعمل من جديد.","example":"يمكن تدوير الورق والزجاج.","page":64,"aliases":["إعادة التدوير"],"visualId":"recycling","unit":"matter4","lesson":"properties","audioText":"التدوير. تحويل مخلفات مواد إلى مواد أو منتجات تستعمل من جديد. مثال. يمكن تدوير الورق والزجاج.","imageQuiz":true},{"id":"physical-change","name":"التغير الفيزيائي","meaning":"تغير في الشكل أو الحجم أو الحالة دون تكون مادة جديدة.","example":"تمزيق الورق تغير فيزيائي.","page":68,"aliases":[],"visualId":"physical-change","unit":"matter4","lesson":"changes4","audioText":"التغير الفيزيائي. تغير في الشكل أو الحجم أو الحالة دون تكون مادة جديدة. مثال. تمزيق الورق تغير فيزيائي.","imageQuiz":false},{"id":"chemical-change","name":"التغير الكيميائي","meaning":"تغير تتكون فيه مادة جديدة تختلف في خصائصها عن المواد الأصلية.","example":"احتراق الخشب تغير كيميائي.","page":72,"aliases":["التفاعل الكيميائي"],"visualId":"chemical-change","unit":"matter4","lesson":"changes4","audioText":"التغير الكيميائي. تغير تتكون فيه مادة جديدة تختلف في خصائصها عن المواد الأصلية. مثال. احتراق الخشب تغير كيميائي.","imageQuiz":false},{"id":"melting","name":"الانصهار","meaning":"تحول المادة من الحالة الصلبة إلى السائلة باكتساب الحرارة.","example":"ينصهر الجليد عند تسخينه.","page":70,"aliases":[],"visualId":"melting","unit":"matter4","lesson":"changes4","audioText":"الانصهار. تحول المادة من الحالة الصلبة إلى السائلة باكتساب الحرارة. مثال. ينصهر الجليد عند تسخينه.","imageQuiz":true},{"id":"evaporation","name":"التبخر","meaning":"تحول المادة السائلة إلى غاز من سطحها.","example":"يجف الماء المتروك في صحن.","page":71,"aliases":[],"visualId":"evaporation","unit":"matter4","lesson":"changes4","audioText":"التبخر. تحول المادة السائلة إلى غاز من سطحها. مثال. يجف الماء المتروك في صحن.","imageQuiz":true},{"id":"condensation","name":"التكاثف","meaning":"تحول الغاز إلى سائل عند فقد الحرارة.","example":"تتكون قطرات ماء على كأس بارد.","page":71,"aliases":[],"visualId":"condensation","unit":"matter4","lesson":"changes4","audioText":"التكاثف. تحول الغاز إلى سائل عند فقد الحرارة. مثال. تتكون قطرات ماء على كأس بارد.","imageQuiz":true},{"id":"freezing","name":"التجمد","meaning":"تحول المادة من السائل إلى الصلب بفقد الحرارة.","example":"يتجمد الماء في المجمدة.","page":71,"aliases":[],"visualId":"freezing","unit":"matter4","lesson":"changes4","audioText":"التجمد. تحول المادة من السائل إلى الصلب بفقد الحرارة. مثال. يتجمد الماء في المجمدة.","imageQuiz":true},{"id":"thermal-expansion","name":"التمدد الحراري","meaning":"زيادة حجم المادة غالبًا عند ارتفاع درجة حرارتها.","example":"يزداد حجم الهواء في البالون عند تدفئته.","page":68,"aliases":[],"visualId":"thermal-expansion","unit":"matter4","lesson":"changes4","audioText":"التمدد الحراري. زيادة حجم المادة غالبًا عند ارتفاع درجة حرارتها. مثال. يزداد حجم الهواء في البالون عند تدفئته.","imageQuiz":true},{"id":"thermal-contraction","name":"الانكماش الحراري","meaning":"نقصان حجم المادة غالبًا عند انخفاض درجة حرارتها.","example":"ينكمش الهواء في البالون عند تبريده.","page":68,"aliases":[],"visualId":"thermal-contraction","unit":"matter4","lesson":"changes4","audioText":"الانكماش الحراري. نقصان حجم المادة غالبًا عند انخفاض درجة حرارتها. مثال. ينكمش الهواء في البالون عند تبريده.","imageQuiz":true},{"id":"rust","name":"صدأ الحديد","meaning":"مادة تتكون عند تفاعل الحديد مع الأكسجين بوجود الرطوبة.","example":"يتكون الصدأ على مسمار حديد رطب.","page":72,"aliases":["الصدأ"],"visualId":"rust","unit":"matter4","lesson":"changes4","audioText":"صدأ الحديد. مادة تتكون عند تفاعل الحديد مع الأكسجين بوجود الرطوبة. مثال. يتكون الصدأ على مسمار حديد رطب.","imageQuiz":true},{"id":"heating","name":"التسخين","meaning":"إمداد المادة بطاقة حرارية، فيزداد نشاط حركة جسيماتها غالبًا.","example":"تنصهر قطعة جليد عند تسخينها.","page":70,"aliases":[],"visualId":"heating","unit":"matter4","lesson":"changes4","audioText":"التسخين. إمداد المادة بطاقة حرارية، فيزداد نشاط حركة جسيماتها غالبًا. مثال. تنصهر قطعة جليد عند تسخينها.","imageQuiz":true},{"id":"cooling","name":"التبريد","meaning":"انتقال طاقة حرارية من المادة إلى محيط أبرد، فتهدأ حركة جسيماتها غالبًا.","example":"يتجمد الماء عند تبريده بدرجة كافية.","page":71,"aliases":[],"visualId":"cooling","unit":"matter4","lesson":"changes4","audioText":"التبريد. انتقال طاقة حرارية من المادة إلى محيط أبرد، فتهدأ حركة جسيماتها غالبًا. مثال. يتجمد الماء عند تبريده بدرجة كافية.","imageQuiz":true},{"id":"water-vapour","name":"بخار الماء","meaning":"الماء في حالته الغازية، وهو غير مرئي.","example":"يوجد بخار ماء في الهواء.","page":71,"aliases":[],"visualId":"water-vapour","unit":"matter4","lesson":"changes4","audioText":"بخار الماء. الماء في حالته الغازية، وهو غير مرئي. مثال. يوجد بخار ماء في الهواء.","imageQuiz":true},{"id":"combustion","name":"الاحتراق","meaning":"تغير كيميائي تتفاعل فيه مادة مع الأكسجين وتطلق طاقة.","example":"احتراق الخشب ينتج مواد جديدة.","page":72,"aliases":[],"visualId":"combustion","unit":"matter4","lesson":"changes4","audioText":"الاحتراق. تغير كيميائي تتفاعل فيه مادة مع الأكسجين وتطلق طاقة. مثال. احتراق الخشب ينتج مواد جديدة.","imageQuiz":true},{"id":"earth","name":"الأرض","meaning":"الكوكب الذي نعيش عليه، ويدور حول الشمس وحول محوره.","example":"تعاقب الليل والنهار ينتج عن دوران الأرض حول محورها.","page":82,"aliases":[],"visualId":"earth","unit":"space","lesson":"earth-moon","audioText":"الأرض. الكوكب الذي نعيش عليه، ويدور حول الشمس وحول محوره. مثال. تعاقب الليل والنهار ينتج عن دوران الأرض حول محورها.","imageQuiz":false},{"id":"sun","name":"الشمس","meaning":"أقرب نجم إلى الأرض، ويصل إلينا منه الضوء والحرارة.","example":"تستفيد النباتات من ضوء الشمس.","page":86,"aliases":[],"visualId":"sun","unit":"space","lesson":"earth-moon","audioText":"الشمس. أقرب نجم إلى الأرض، ويصل إلينا منه الضوء والحرارة. مثال. تستفيد النباتات من ضوء الشمس.","imageQuiz":false},{"id":"moon","name":"القمر","meaning":"تابع طبيعي للأرض، يعكس ضوء الشمس ولا يضيء بذاته.","example":"نرى الجزء المضيء من القمر في الليل.","page":86,"aliases":[],"visualId":"moon","unit":"space","lesson":"earth-moon","audioText":"القمر. تابع طبيعي للأرض، يعكس ضوء الشمس ولا يضيء بذاته. مثال. نرى الجزء المضيء من القمر في الليل.","imageQuiz":false},{"id":"rotation","name":"الدوران حول المحور","meaning":"حركة الجسم حول خط يمر فيه يسمى المحور.","example":"تدور الأرض حول محورها مرة كل يوم تقريبًا.","page":82,"aliases":["الدوران المحوري"],"visualId":"rotation","unit":"space","lesson":"earth-moon","audioText":"الدوران حول المحور. حركة الجسم حول خط يمر فيه يسمى المحور. مثال. تدور الأرض حول محورها مرة كل يوم تقريبًا.","imageQuiz":false},{"id":"revolution","name":"الحركة الدورانية","meaning":"حركة جسم حول جسم آخر في مدار، كما يستعمل المصطلح في الدرس.","example":"تتحرك الأرض حول الشمس.","page":82,"aliases":["الدوران حول الشمس"],"visualId":"revolution","unit":"space","lesson":"earth-moon","audioText":"الحركة الدورانية. حركة جسم حول جسم آخر في مدار، كما يستعمل المصطلح في الدرس. مثال. تتحرك الأرض حول الشمس.","imageQuiz":false},{"id":"axis","name":"المحور","meaning":"خط حقيقي أو وهمي يدور حوله الجسم.","example":"يمر محور الأرض بقطبيها.","page":82,"aliases":[],"visualId":"axis","unit":"space","lesson":"earth-moon","audioText":"المحور. خط حقيقي أو وهمي يدور حوله الجسم. مثال. يمر محور الأرض بقطبيها.","imageQuiz":true},{"id":"orbit","name":"المدار","meaning":"مسار يتحرك فيه جسم حول جسم آخر.","example":"تتحرك الأرض في مدار حول الشمس.","page":84,"aliases":[],"visualId":"orbit","unit":"space","lesson":"earth-moon","audioText":"المدار. مسار يتحرك فيه جسم حول جسم آخر. مثال. تتحرك الأرض في مدار حول الشمس.","imageQuiz":false},{"id":"equator","name":"خط الاستواء","meaning":"خط وهمي يقسم الأرض إلى نصف شمالي ونصف جنوبي.","example":"يقع خط الاستواء في منتصف المسافة بين القطبين.","page":82,"aliases":[],"visualId":"equator","unit":"space","lesson":"earth-moon","audioText":"خط الاستواء. خط وهمي يقسم الأرض إلى نصف شمالي ونصف جنوبي. مثال. يقع خط الاستواء في منتصف المسافة بين القطبين.","imageQuiz":true},{"id":"north-pole","name":"القطب الشمالي","meaning":"نهاية محور دوران الأرض في جهة الشمال.","example":"يشير أحد طرفي محور الأرض إلى القطب الشمالي.","page":82,"aliases":[],"visualId":"north-pole","unit":"space","lesson":"earth-moon","audioText":"القطب الشمالي. نهاية محور دوران الأرض في جهة الشمال. مثال. يشير أحد طرفي محور الأرض إلى القطب الشمالي.","imageQuiz":true},{"id":"south-pole","name":"القطب الجنوبي","meaning":"نهاية محور دوران الأرض في جهة الجنوب.","example":"يشير الطرف المقابل للمحور إلى القطب الجنوبي.","page":82,"aliases":[],"visualId":"south-pole","unit":"space","lesson":"earth-moon","audioText":"القطب الجنوبي. نهاية محور دوران الأرض في جهة الجنوب. مثال. يشير الطرف المقابل للمحور إلى القطب الجنوبي.","imageQuiz":true},{"id":"day-night","name":"الليل والنهار","meaning":"تعاقب الإضاءة والظلام نتيجة دوران الأرض حول محورها.","example":"الجزء المواجه للشمس يكون في النهار.","page":83,"aliases":[],"visualId":"day-night","unit":"space","lesson":"earth-moon","audioText":"الليل والنهار. تعاقب الإضاءة والظلام نتيجة دوران الأرض حول محورها. مثال. الجزء المواجه للشمس يكون في النهار.","imageQuiz":false},{"id":"shadow","name":"الظل","meaning":"منطقة يقل فيها الضوء لأن جسمًا حجب أشعته.","example":"يتكون ظل للطالبة عند وقوفها في الشمس.","page":83,"aliases":[],"visualId":"shadow","unit":"space","lesson":"earth-moon","audioText":"الظل. منطقة يقل فيها الضوء لأن جسمًا حجب أشعته. مثال. يتكون ظل للطالبة عند وقوفها في الشمس.","imageQuiz":true},{"id":"apparent-motion","name":"الحركة الظاهرية","meaning":"حركة تبدو للمشاهد بسبب حركة موقعه، مثل ظهور الشمس كأنها تتحرك في السماء.","example":"تبدو الشمس كأنها تنتقل من الشروق إلى الغروب.","page":83,"aliases":[],"visualId":"apparent-motion","unit":"space","lesson":"earth-moon","audioText":"الحركة الظاهرية. حركة تبدو للمشاهد بسبب حركة موقعه، مثل ظهور الشمس كأنها تتحرك في السماء. مثال. تبدو الشمس كأنها تنتقل من الشروق إلى الغروب.","imageQuiz":false},{"id":"seasons","name":"الفصول الأربعة","meaning":"الربيع والصيف والخريف والشتاء، وتنتج عن ميل محور الأرض ودورانها حول الشمس.","example":"يختلف مقدار ضوء الشمس الواصل إلى المكان عبر السنة.","page":84,"aliases":[],"visualId":"seasons","unit":"space","lesson":"earth-moon","audioText":"الفصول الأربعة. الربيع والصيف والخريف والشتاء، وتنتج عن ميل محور الأرض ودورانها حول الشمس. مثال. يختلف مقدار ضوء الشمس الواصل إلى المكان عبر السنة.","imageQuiz":false},{"id":"lunar-crater","name":"الفوهات القمرية","meaning":"حفر على سطح القمر تكون كثير منها بفعل اصطدام أجسام صخرية به.","example":"نرى فوهات دائرية على سطح القمر.","page":87,"aliases":["فوهات القمر","الفوهات"],"visualId":"lunar-crater","unit":"space","lesson":"earth-moon","audioText":"الفوهات القمرية. حفر على سطح القمر تكون كثير منها بفعل اصطدام أجسام صخرية به. مثال. نرى فوهات دائرية على سطح القمر.","imageQuiz":true},{"id":"moon-phases","name":"أطوار القمر","meaning":"الأشكال الظاهرية للجزء المضيء من القمر كما نراه من الأرض.","example":"يتدرج شكل القمر بين الهلال والبدر.","page":88,"aliases":[],"visualId":"moon-phases","unit":"space","lesson":"earth-moon","audioText":"أطوار القمر. الأشكال الظاهرية للجزء المضيء من القمر كما نراه من الأرض. مثال. يتدرج شكل القمر بين الهلال والبدر.","imageQuiz":false},{"id":"new-moon","name":"المحاق","meaning":"طور لا نرى فيه الجزء المضيء من القمر من الأرض عادة.","example":"يكون المحاق قرب بداية الدورة القمرية.","page":88,"aliases":[],"visualId":"new-moon","unit":"space","lesson":"earth-moon","audioText":"المحاق. طور لا نرى فيه الجزء المضيء من القمر من الأرض عادة. مثال. يكون المحاق قرب بداية الدورة القمرية.","imageQuiz":true},{"id":"crescent","name":"الهلال","meaning":"طور نرى فيه جزءًا رفيعًا مضيئًا من قرص القمر.","example":"نرى الهلال في بداية الشهر القمري.","page":88,"aliases":[],"visualId":"crescent","unit":"space","lesson":"earth-moon","audioText":"الهلال. طور نرى فيه جزءًا رفيعًا مضيئًا من قرص القمر. مثال. نرى الهلال في بداية الشهر القمري.","imageQuiz":true},{"id":"first-quarter","name":"التربيع الأول","meaning":"طور نرى فيه نصف قرص القمر مضيئًا وهو يتزايد.","example":"يأتي التربيع الأول بعد الهلال المتزايد.","page":88,"aliases":[],"visualId":"first-quarter","unit":"space","lesson":"earth-moon","audioText":"التربيع الأول. طور نرى فيه نصف قرص القمر مضيئًا وهو يتزايد. مثال. يأتي التربيع الأول بعد الهلال المتزايد.","imageQuiz":true},{"id":"gibbous","name":"الأحدب","meaning":"طور يبدو فيه أكثر من نصف قرص القمر مضيئًا وأقل من كامل القرص.","example":"يظهر الأحدب قبل البدر أو بعده.","page":88,"aliases":[],"visualId":"gibbous","unit":"space","lesson":"earth-moon","audioText":"الأحدب. طور يبدو فيه أكثر من نصف قرص القمر مضيئًا وأقل من كامل القرص. مثال. يظهر الأحدب قبل البدر أو بعده.","imageQuiz":true},{"id":"full-moon","name":"البدر","meaning":"طور يبدو فيه قرص القمر كامل الإضاءة من الأرض.","example":"نرى البدر قرب منتصف الشهر القمري.","page":89,"aliases":[],"visualId":"full-moon","unit":"space","lesson":"earth-moon","audioText":"البدر. طور يبدو فيه قرص القمر كامل الإضاءة من الأرض. مثال. نرى البدر قرب منتصف الشهر القمري.","imageQuiz":true},{"id":"last-quarter","name":"التربيع الأخير","meaning":"طور نرى فيه نصف قرص القمر مضيئًا وهو يتناقص.","example":"يأتي التربيع الأخير بعد الأحدب المتناقص.","page":89,"aliases":[],"visualId":"last-quarter","unit":"space","lesson":"earth-moon","audioText":"التربيع الأخير. طور نرى فيه نصف قرص القمر مضيئًا وهو يتناقص. مثال. يأتي التربيع الأخير بعد الأحدب المتناقص.","imageQuiz":true},{"id":"gravity","name":"الجاذبية","meaning":"قوة تجاذب بين الأجسام، وتجذب الأرض بها الأشياء نحوها.","example":"تسقط الكرة نحو الأرض بفعل الجاذبية.","page":88,"aliases":[],"visualId":"gravity","unit":"space","lesson":"earth-moon","audioText":"الجاذبية. قوة تجاذب بين الأجسام، وتجذب الأرض بها الأشياء نحوها. مثال. تسقط الكرة نحو الأرض بفعل الجاذبية.","imageQuiz":false},{"id":"tides","name":"المد والجزر","meaning":"ارتفاع مستوى ماء البحر وانخفاضه دوريًا، ويتأثر بجاذبية القمر والشمس.","example":"يتغير مستوى الماء قرب الشاطئ عبر اليوم.","page":89,"aliases":[],"visualId":"tides","unit":"space","lesson":"earth-moon","audioText":"المد والجزر. ارتفاع مستوى ماء البحر وانخفاضه دوريًا، ويتأثر بجاذبية القمر والشمس. مثال. يتغير مستوى الماء قرب الشاطئ عبر اليوم.","imageQuiz":false},{"id":"lunar-eclipse","name":"خسوف القمر","meaning":"دخول القمر في ظل الأرض عندما تقع الأرض بين الشمس والقمر.","example":"يقل ضوء القمر عند دخوله ظل الأرض.","page":90,"aliases":[],"visualId":"lunar-eclipse","unit":"space","lesson":"earth-moon","audioText":"خسوف القمر. دخول القمر في ظل الأرض عندما تقع الأرض بين الشمس والقمر. مثال. يقل ضوء القمر عند دخوله ظل الأرض.","imageQuiz":true},{"id":"solar-eclipse","name":"كسوف الشمس","meaning":"احتجاب الشمس أو جزء منها عنا عندما يقع القمر بين الأرض والشمس.","example":"يحجب القمر جزءًا من ضوء الشمس عن بعض مناطق الأرض.","page":90,"aliases":[],"visualId":"solar-eclipse","unit":"space","lesson":"earth-moon","audioText":"كسوف الشمس. احتجاب الشمس أو جزء منها عنا عندما يقع القمر بين الأرض والشمس. مثال. يحجب القمر جزءًا من ضوء الشمس عن بعض مناطق الأرض.","imageQuiz":true},{"id":"atmosphere","name":"الغلاف الجوي","meaning":"غطاء من الغازات يحيط بالأرض.","example":"نعيش في الجزء السفلي من الغلاف الجوي.","page":88,"aliases":[],"visualId":"atmosphere","unit":"space","lesson":"earth-moon","audioText":"الغلاف الجوي. غطاء من الغازات يحيط بالأرض. مثال. نعيش في الجزء السفلي من الغلاف الجوي.","imageQuiz":true},{"id":"satellite","name":"التابع","meaning":"جسم يدور في مدار حول جسم أكبر منه.","example":"القمر تابع طبيعي للأرض.","page":94,"aliases":[],"visualId":"satellite","unit":"space","lesson":"solar","audioText":"التابع. جسم يدور في مدار حول جسم أكبر منه. مثال. القمر تابع طبيعي للأرض.","imageQuiz":true},{"id":"artificial-satellite","name":"القمر الصناعي","meaning":"جهاز يصنعه الإنسان ويضعه في مدار، ومنها أقمار تدور حول الأرض.","example":"تساعد بعض الأقمار الصناعية في الاتصالات.","page":94,"aliases":["القمر الاصطناعي"],"visualId":"artificial-satellite","unit":"space","lesson":"solar","audioText":"القمر الصناعي. جهاز يصنعه الإنسان ويضعه في مدار، ومنها أقمار تدور حول الأرض. مثال. تساعد بعض الأقمار الصناعية في الاتصالات.","imageQuiz":true},{"id":"solar-system","name":"النظام الشمسي","meaning":"الشمس والأجرام التي تدور حولها، ومنها الكواكب وأقمارها.","example":"الأرض أحد كواكب النظام الشمسي.","page":94,"aliases":[],"visualId":"solar-system","unit":"space","lesson":"solar","audioText":"النظام الشمسي. الشمس والأجرام التي تدور حولها، ومنها الكواكب وأقمارها. مثال. الأرض أحد كواكب النظام الشمسي.","imageQuiz":true},{"id":"planet","name":"الكوكب","meaning":"جرم كروي تقريبًا يدور حول نجم ولا يضيء من ذاته.","example":"تدور الأرض حول الشمس وتعكس ضوءها.","page":94,"aliases":["الكواكب"],"visualId":"planet","unit":"space","lesson":"solar","audioText":"الكوكب. جرم كروي تقريبًا يدور حول نجم ولا يضيء من ذاته. مثال. تدور الأرض حول الشمس وتعكس ضوءها.","imageQuiz":false},{"id":"rocky-planets","name":"الكواكب الصخرية","meaning":"الكواكب الداخلية ذات الأسطح الصخرية، وهي عطارد والزهرة والأرض والمريخ.","example":"الأرض من الكواكب الصخرية.","page":96,"aliases":[],"visualId":"rocky-planets","unit":"space","lesson":"solar","audioText":"الكواكب الصخرية. الكواكب الداخلية ذات الأسطح الصخرية، وهي عطارد والزهرة والأرض والمريخ. مثال. الأرض من الكواكب الصخرية.","imageQuiz":false},{"id":"giant-planets","name":"الكواكب العملاقة","meaning":"الكواكب الخارجية الكبيرة: المشتري وزحل وأورانوس ونبتون، كما يجمعها الدرس.","example":"زحل كوكب عملاق تحيط به حلقات.","page":96,"aliases":["الكواكب الغازية العملاقة"],"visualId":"giant-planets","unit":"space","lesson":"solar","audioText":"الكواكب العملاقة. الكواكب الخارجية الكبيرة: المشتري وزحل وأورانوس ونبتون، كما يجمعها الدرس. مثال. زحل كوكب عملاق تحيط به حلقات.","imageQuiz":false},{"id":"mercury","name":"عطارد","meaning":"أقرب كواكب النظام الشمسي إلى الشمس.","example":"مدار عطارد أقرب إلى الشمس من مدار الأرض.","page":95,"aliases":[],"visualId":"mercury","unit":"space","lesson":"solar","audioText":"عطارد. أقرب كواكب النظام الشمسي إلى الشمس. مثال. مدار عطارد أقرب إلى الشمس من مدار الأرض.","imageQuiz":true},{"id":"venus","name":"الزهرة","meaning":"الكوكب الثاني في ترتيب البعد عن الشمس.","example":"يقع مدار الزهرة بين عطارد والأرض.","page":95,"aliases":[],"visualId":"venus","unit":"space","lesson":"solar","audioText":"الزهرة. الكوكب الثاني في ترتيب البعد عن الشمس. مثال. يقع مدار الزهرة بين عطارد والأرض.","imageQuiz":true},{"id":"mars","name":"المريخ","meaning":"الكوكب الرابع من الشمس، ويبدو مائلًا إلى الحمرة.","example":"يأتي المريخ بعد الأرض في ترتيب الكواكب.","page":95,"aliases":[],"visualId":"mars","unit":"space","lesson":"solar","audioText":"المريخ. الكوكب الرابع من الشمس، ويبدو مائلًا إلى الحمرة. مثال. يأتي المريخ بعد الأرض في ترتيب الكواكب.","imageQuiz":true},{"id":"jupiter","name":"المشتري","meaning":"أكبر كواكب النظام الشمسي، وخامسها بعدًا عن الشمس.","example":"المشتري أكبر من الأرض بكثير.","page":95,"aliases":[],"visualId":"jupiter","unit":"space","lesson":"solar","audioText":"المشتري. أكبر كواكب النظام الشمسي، وخامسها بعدًا عن الشمس. مثال. المشتري أكبر من الأرض بكثير.","imageQuiz":true},{"id":"saturn","name":"زحل","meaning":"الكوكب السادس من الشمس، وتحيط به حلقات واضحة.","example":"تساعدنا الحلقات على تمييز صورة زحل.","page":95,"aliases":[],"visualId":"saturn","unit":"space","lesson":"solar","audioText":"زحل. الكوكب السادس من الشمس، وتحيط به حلقات واضحة. مثال. تساعدنا الحلقات على تمييز صورة زحل.","imageQuiz":true},{"id":"uranus","name":"أورانوس","meaning":"الكوكب السابع من الشمس، ولونه مائل إلى الأزرق المخضر.","example":"يقع أورانوس بين زحل ونبتون.","page":95,"aliases":[],"visualId":"uranus","unit":"space","lesson":"solar","audioText":"أورانوس. الكوكب السابع من الشمس، ولونه مائل إلى الأزرق المخضر. مثال. يقع أورانوس بين زحل ونبتون.","imageQuiz":true},{"id":"neptune","name":"نبتون","meaning":"الكوكب الثامن والأبعد عن الشمس بين الكواكب الثمانية.","example":"يأتي نبتون بعد أورانوس.","page":95,"aliases":[],"visualId":"neptune","unit":"space","lesson":"solar","audioText":"نبتون. الكوكب الثامن والأبعد عن الشمس بين الكواكب الثمانية. مثال. يأتي نبتون بعد أورانوس.","imageQuiz":true},{"id":"comet","name":"المذنب","meaning":"جرم من الجليد والغبار والصخور يدور حول الشمس، وقد يظهر له ذيل عند اقترابه منها.","example":"يظهر للمذنب ذيل من الغاز والغبار.","page":97,"aliases":[],"visualId":"comet","unit":"space","lesson":"solar","audioText":"المذنب. جرم من الجليد والغبار والصخور يدور حول الشمس، وقد يظهر له ذيل عند اقترابه منها. مثال. يظهر للمذنب ذيل من الغاز والغبار.","imageQuiz":true},{"id":"asteroid","name":"الكويكب","meaning":"جرم صخري صغير نسبيًا يدور حول الشمس.","example":"يقع كثير من الكويكبات بين المريخ والمشتري.","page":97,"aliases":["الكويكبات"],"visualId":"asteroid","unit":"space","lesson":"solar","audioText":"الكويكب. جرم صخري صغير نسبيًا يدور حول الشمس. مثال. يقع كثير من الكويكبات بين المريخ والمشتري.","imageQuiz":true},{"id":"asteroid-belt","name":"حزام الكويكبات","meaning":"منطقة بين مداري المريخ والمشتري يوجد فيها عدد كبير من الكويكبات.","example":"تمر منطقة حزام الكويكبات خارج مدار المريخ.","page":97,"aliases":[],"visualId":"asteroid-belt","unit":"space","lesson":"solar","audioText":"حزام الكويكبات. منطقة بين مداري المريخ والمشتري يوجد فيها عدد كبير من الكويكبات. مثال. تمر منطقة حزام الكويكبات خارج مدار المريخ.","imageQuiz":true},{"id":"meteor","name":"الشهاب","meaning":"الخط المضيء الناتج عن دخول جسم صغير الغلاف الجوي وتسخنه.","example":"قد نرى شهابًا كخط مضيء في السماء.","page":97,"aliases":["الشهب"],"visualId":"meteor","unit":"space","lesson":"solar","audioText":"الشهاب. الخط المضيء الناتج عن دخول جسم صغير الغلاف الجوي وتسخنه. مثال. قد نرى شهابًا كخط مضيء في السماء.","imageQuiz":true},{"id":"meteorite","name":"النيزك","meaning":"جزء من جسم فضائي يصل إلى سطح الأرض.","example":"قد يترك اصطدام نيزك حفرة في الأرض.","page":97,"aliases":["النيازك"],"visualId":"meteorite","unit":"space","lesson":"solar","audioText":"النيزك. جزء من جسم فضائي يصل إلى سطح الأرض. مثال. قد يترك اصطدام نيزك حفرة في الأرض.","imageQuiz":true},{"id":"star","name":"النجم","meaning":"جرم كبير من غازات ساخنة يصدر الضوء والحرارة.","example":"الشمس نجم.","page":98,"aliases":["النجوم"],"visualId":"star","unit":"space","lesson":"solar","audioText":"النجم. جرم كبير من غازات ساخنة يصدر الضوء والحرارة. مثال. الشمس نجم.","imageQuiz":true},{"id":"galaxy","name":"المجرة","meaning":"مجموعة هائلة من النجوم والغاز والغبار مرتبطة بالجاذبية.","example":"توجد الشمس في مجرة درب التبانة.","page":98,"aliases":["المجرات"],"visualId":"galaxy","unit":"space","lesson":"solar","audioText":"المجرة. مجموعة هائلة من النجوم والغاز والغبار مرتبطة بالجاذبية. مثال. توجد الشمس في مجرة درب التبانة.","imageQuiz":true},{"id":"milky-way","name":"درب التبانة","meaning":"المجرة التي تنتمي إليها الشمس والنظام الشمسي.","example":"نظامنا الشمسي جزء صغير من درب التبانة.","page":98,"aliases":["مجرة درب التبانة"],"visualId":"milky-way","unit":"space","lesson":"solar","audioText":"درب التبانة. المجرة التي تنتمي إليها الشمس والنظام الشمسي. مثال. نظامنا الشمسي جزء صغير من درب التبانة.","imageQuiz":true},{"id":"constellation","name":"البرج السماوي","meaning":"مجموعة نجوم تبدو لنا في شكل معين في السماء.","example":"الدب الأكبر من المجموعات النجمية المذكورة في الدرس.","page":99,"aliases":["المجموعة النجمية","البروج السماوية","البرج"],"visualId":"constellation","unit":"space","lesson":"solar","audioText":"البرج السماوي. مجموعة نجوم تبدو لنا في شكل معين في السماء. مثال. الدب الأكبر من المجموعات النجمية المذكورة في الدرس.","imageQuiz":true},{"id":"digestion","name":"الهضم","meaning":"تفكيك الغذاء إلى أجزاء صغيرة يمكن للجسم امتصاصها والاستفادة منها.","example":"يبدأ هضم الطعام في الفم.","page":108,"aliases":[],"visualId":"digestion","unit":"health","lesson":"systems","audioText":"الهضم. تفكيك الغذاء إلى أجزاء صغيرة يمكن للجسم امتصاصها والاستفادة منها. مثال. يبدأ هضم الطعام في الفم.","imageQuiz":false},{"id":"digestive-system","name":"الجهاز الهضمي","meaning":"أعضاء تتعاون لهضم الغذاء وامتصاصه والتخلص من بقاياه.","example":"الفم والمعدة والأمعاء أجزاء من الجهاز الهضمي.","page":108,"aliases":[],"visualId":"digestive-system","unit":"health","lesson":"systems","audioText":"الجهاز الهضمي. أعضاء تتعاون لهضم الغذاء وامتصاصه والتخلص من بقاياه. مثال. الفم والمعدة والأمعاء أجزاء من الجهاز الهضمي.","imageQuiz":false},{"id":"mouth","name":"الفم","meaning":"مدخل الطعام، وفيه تمضغ الأسنان الطعام ويختلط باللعاب.","example":"تمضغ الطالبة الطعام في الفم.","page":108,"aliases":[],"visualId":"mouth","unit":"health","lesson":"systems","audioText":"الفم. مدخل الطعام، وفيه تمضغ الأسنان الطعام ويختلط باللعاب. مثال. تمضغ الطالبة الطعام في الفم.","imageQuiz":true},{"id":"saliva","name":"اللعاب","meaning":"سائل في الفم يرطب الطعام ويبدأ هضم بعض مكوناته.","example":"يختلط الخبز باللعاب أثناء المضغ.","page":108,"aliases":[],"visualId":"saliva","unit":"health","lesson":"systems","audioText":"اللعاب. سائل في الفم يرطب الطعام ويبدأ هضم بعض مكوناته. مثال. يختلط الخبز باللعاب أثناء المضغ.","imageQuiz":true},{"id":"oesophagus","name":"المريء","meaning":"أنبوب عضلي ينقل الطعام من البلعوم إلى المعدة.","example":"ينتقل الطعام إلى المعدة عبر المريء.","page":108,"aliases":["المرئ"],"visualId":"oesophagus","unit":"health","lesson":"systems","audioText":"المريء. أنبوب عضلي ينقل الطعام من البلعوم إلى المعدة. مثال. ينتقل الطعام إلى المعدة عبر المريء.","imageQuiz":true},{"id":"stomach","name":"المعدة","meaning":"عضو عضلي يخلط الطعام بعصارات تساعد على هضمه.","example":"يتابع الطعام هضمه داخل المعدة.","page":108,"aliases":[],"visualId":"stomach","unit":"health","lesson":"systems","audioText":"المعدة. عضو عضلي يخلط الطعام بعصارات تساعد على هضمه. مثال. يتابع الطعام هضمه داخل المعدة.","imageQuiz":true},{"id":"liver","name":"الكبد","meaning":"عضو ينتج العصارة الصفراوية وله وظائف عديدة في معالجة المواد في الجسم.","example":"يسهم الكبد في المساعدة على هضم الدهون.","page":108,"aliases":[],"visualId":"liver","unit":"health","lesson":"systems","audioText":"الكبد. عضو ينتج العصارة الصفراوية وله وظائف عديدة في معالجة المواد في الجسم. مثال. يسهم الكبد في المساعدة على هضم الدهون.","imageQuiz":true},{"id":"pancreas","name":"البنكرياس","meaning":"غدة تفرز عصارات تساعد على هضم الغذاء.","example":"تصل عصارات البنكرياس إلى الأمعاء الدقيقة.","page":108,"aliases":[],"visualId":"pancreas","unit":"health","lesson":"systems","audioText":"البنكرياس. غدة تفرز عصارات تساعد على هضم الغذاء. مثال. تصل عصارات البنكرياس إلى الأمعاء الدقيقة.","imageQuiz":true},{"id":"small-intestine","name":"الأمعاء الدقيقة","meaning":"أنبوب يكتمل فيه معظم الهضم ويمتص كثيرًا من المواد الغذائية.","example":"تنتقل المغذيات من الأمعاء الدقيقة إلى الدم.","page":108,"aliases":[],"visualId":"small-intestine","unit":"health","lesson":"systems","audioText":"الأمعاء الدقيقة. أنبوب يكتمل فيه معظم الهضم ويمتص كثيرًا من المواد الغذائية. مثال. تنتقل المغذيات من الأمعاء الدقيقة إلى الدم.","imageQuiz":true},{"id":"large-intestine","name":"الأمعاء الغليظة","meaning":"جزء يعيد امتصاص الماء من بقايا الطعام ويساعد في تكوين الفضلات الصلبة.","example":"تمر بقايا الطعام بالأمعاء الغليظة.","page":108,"aliases":[],"visualId":"large-intestine","unit":"health","lesson":"systems","audioText":"الأمعاء الغليظة. جزء يعيد امتصاص الماء من بقايا الطعام ويساعد في تكوين الفضلات الصلبة. مثال. تمر بقايا الطعام بالأمعاء الغليظة.","imageQuiz":true},{"id":"excretion","name":"الإخراج","meaning":"تخلص الجسم من الفضلات والمواد الزائدة.","example":"تطرح الكليتان فضلات وماءً زائدًا مع البول.","page":109,"aliases":[],"visualId":"excretion","unit":"health","lesson":"systems","audioText":"الإخراج. تخلص الجسم من الفضلات والمواد الزائدة. مثال. تطرح الكليتان فضلات وماءً زائدًا مع البول.","imageQuiz":false},{"id":"urinary-system","name":"الجهاز البولي","meaning":"أعضاء تخلص الدم من فضلات وتخرج البول من الجسم.","example":"الكليتان والمثانة من أجزاء الجهاز البولي.","page":109,"aliases":[],"visualId":"urinary-system","unit":"health","lesson":"systems","audioText":"الجهاز البولي. أعضاء تخلص الدم من فضلات وتخرج البول من الجسم. مثال. الكليتان والمثانة من أجزاء الجهاز البولي.","imageQuiz":false},{"id":"kidneys","name":"الكليتان","meaning":"عضوان يرشحان الدم ويضبطان الماء والأملاح ويكوّنان البول.","example":"تزيل الكليتان فضلات من الدم.","page":109,"aliases":["الكلى"],"visualId":"kidneys","unit":"health","lesson":"systems","audioText":"الكليتان. عضوان يرشحان الدم ويضبطان الماء والأملاح ويكوّنان البول. مثال. تزيل الكليتان فضلات من الدم.","imageQuiz":true},{"id":"nephron","name":"النفرون","meaning":"وحدة دقيقة في الكلية ترشح الدم وتشارك في تكوين البول.","example":"تحتوي الكلية على أعداد كبيرة من النفرونات.","page":109,"aliases":["النفرونات"],"visualId":"nephron","unit":"health","lesson":"systems","audioText":"النفرون. وحدة دقيقة في الكلية ترشح الدم وتشارك في تكوين البول. مثال. تحتوي الكلية على أعداد كبيرة من النفرونات.","imageQuiz":true},{"id":"ureter","name":"الحالب","meaning":"أنبوب ينقل البول من الكلية إلى المثانة.","example":"ينتقل البول عبر الحالبين.","page":109,"aliases":["الحالبان"],"visualId":"ureter","unit":"health","lesson":"systems","audioText":"الحالب. أنبوب ينقل البول من الكلية إلى المثانة. مثال. ينتقل البول عبر الحالبين.","imageQuiz":true},{"id":"bladder","name":"المثانة البولية","meaning":"عضو يجمع البول مؤقتًا قبل خروجه من الجسم.","example":"يصل البول من الكليتين إلى المثانة.","page":109,"aliases":["المثانة"],"visualId":"bladder","unit":"health","lesson":"systems","audioText":"المثانة البولية. عضو يجمع البول مؤقتًا قبل خروجه من الجسم. مثال. يصل البول من الكليتين إلى المثانة.","imageQuiz":true},{"id":"urethra","name":"مجرى البول","meaning":"أنبوب ينقل البول من المثانة إلى خارج الجسم.","example":"يخرج البول عبر مجرى البول.","page":109,"aliases":[],"visualId":"urethra","unit":"health","lesson":"systems","audioText":"مجرى البول. أنبوب ينقل البول من المثانة إلى خارج الجسم. مثال. يخرج البول عبر مجرى البول.","imageQuiz":true},{"id":"breathing","name":"التنفس","meaning":"دخول الهواء وخروجه وتبادل الأكسجين وثاني أكسيد الكربون في الرئتين.","example":"يدخل الهواء إلى الرئتين عند الشهيق.","page":110,"aliases":[],"visualId":"breathing","unit":"health","lesson":"systems","audioText":"التنفس. دخول الهواء وخروجه وتبادل الأكسجين وثاني أكسيد الكربون في الرئتين. مثال. يدخل الهواء إلى الرئتين عند الشهيق.","imageQuiz":false},{"id":"respiratory-system","name":"الجهاز التنفسي","meaning":"أعضاء تدخل الهواء إلى الرئتين وتساعد على تبادل الغازات.","example":"الأنف والقصبة الهوائية والرئتان من أجزائه.","page":110,"aliases":[],"visualId":"respiratory-system","unit":"health","lesson":"systems","audioText":"الجهاز التنفسي. أعضاء تدخل الهواء إلى الرئتين وتساعد على تبادل الغازات. مثال. الأنف والقصبة الهوائية والرئتان من أجزائه.","imageQuiz":false},{"id":"pharynx","name":"البلعوم","meaning":"ممر خلف الأنف والفم يمر فيه الهواء والطعام في مسارين مختلفين لاحقًا.","example":"يمر الهواء من الأنف إلى البلعوم.","page":110,"aliases":[],"visualId":"pharynx","unit":"health","lesson":"systems","audioText":"البلعوم. ممر خلف الأنف والفم يمر فيه الهواء والطعام في مسارين مختلفين لاحقًا. مثال. يمر الهواء من الأنف إلى البلعوم.","imageQuiz":true},{"id":"larynx","name":"الحنجرة","meaning":"جزء من مجرى الهواء يحوي الأحبال الصوتية ويتصل بالقصبة الهوائية.","example":"يمر الهواء عبر الحنجرة.","page":110,"aliases":[],"visualId":"larynx","unit":"health","lesson":"systems","audioText":"الحنجرة. جزء من مجرى الهواء يحوي الأحبال الصوتية ويتصل بالقصبة الهوائية. مثال. يمر الهواء عبر الحنجرة.","imageQuiz":true},{"id":"trachea","name":"القصبة الهوائية","meaning":"أنبوب ينقل الهواء من الحنجرة إلى الشعبتين الهوائيتين.","example":"تتصل القصبة الهوائية بالشعبتين الداخلتين إلى الرئتين.","page":110,"aliases":[],"visualId":"trachea","unit":"health","lesson":"systems","audioText":"القصبة الهوائية. أنبوب ينقل الهواء من الحنجرة إلى الشعبتين الهوائيتين. مثال. تتصل القصبة الهوائية بالشعبتين الداخلتين إلى الرئتين.","imageQuiz":true},{"id":"bronchi","name":"الشعبتان الهوائيتان","meaning":"فرعان رئيسان من القصبة الهوائية، يدخل كل منهما إلى رئة.","example":"تتفرع الشعبتان إلى أنابيب أصغر داخل الرئتين.","page":110,"aliases":["الشعب الهوائية"],"visualId":"bronchi","unit":"health","lesson":"systems","audioText":"الشعبتان الهوائيتان. فرعان رئيسان من القصبة الهوائية، يدخل كل منهما إلى رئة. مثال. تتفرع الشعبتان إلى أنابيب أصغر داخل الرئتين.","imageQuiz":true},{"id":"bronchioles","name":"الشعيبات الهوائية","meaning":"أنابيب صغيرة متفرعة داخل الرئتين تنتهي بحويصلات هوائية.","example":"ينتقل الهواء عبر الشعيبات إلى الحويصلات.","page":110,"aliases":[],"visualId":"bronchioles","unit":"health","lesson":"systems","audioText":"الشعيبات الهوائية. أنابيب صغيرة متفرعة داخل الرئتين تنتهي بحويصلات هوائية. مثال. ينتقل الهواء عبر الشعيبات إلى الحويصلات.","imageQuiz":true},{"id":"alveoli","name":"الحويصلات الهوائية","meaning":"أكياس دقيقة في الرئتين يتم عبر جدرانها الرقيقة تبادل الغازات مع الدم.","example":"ينتقل الأكسجين من الحويصلات إلى الدم.","page":110,"aliases":["الحويصلة الهوائية"],"visualId":"alveoli","unit":"health","lesson":"systems","audioText":"الحويصلات الهوائية. أكياس دقيقة في الرئتين يتم عبر جدرانها الرقيقة تبادل الغازات مع الدم. مثال. ينتقل الأكسجين من الحويصلات إلى الدم.","imageQuiz":true},{"id":"lungs","name":"الرئتان","meaning":"عضوان في الصدر يحدث داخلهما تبادل الغازات بين الهواء والدم.","example":"تمتلئ الرئتان بالهواء عند الشهيق.","page":110,"aliases":["الرئة"],"visualId":"lungs","unit":"health","lesson":"systems","audioText":"الرئتان. عضوان في الصدر يحدث داخلهما تبادل الغازات بين الهواء والدم. مثال. تمتلئ الرئتان بالهواء عند الشهيق.","imageQuiz":true},{"id":"diaphragm","name":"الحجاب الحاجز","meaning":"عضلة أسفل الرئتين تساعد حركتها على الشهيق والزفير.","example":"يتحرك الحجاب الحاجز عندما نتنفس.","page":110,"aliases":["عضلة الحجاب الحاجز"],"visualId":"diaphragm","unit":"health","lesson":"systems","audioText":"الحجاب الحاجز. عضلة أسفل الرئتين تساعد حركتها على الشهيق والزفير. مثال. يتحرك الحجاب الحاجز عندما نتنفس.","imageQuiz":true},{"id":"circulation","name":"الدوران","meaning":"حركة الدم وما يحمله من مواد بين القلب والرئتين وأجزاء الجسم.","example":"ينقل الدم الأكسجين والغذاء إلى الخلايا.","page":111,"aliases":[],"visualId":"circulation","unit":"health","lesson":"systems","audioText":"الدوران. حركة الدم وما يحمله من مواد بين القلب والرئتين وأجزاء الجسم. مثال. ينقل الدم الأكسجين والغذاء إلى الخلايا.","imageQuiz":false},{"id":"circulatory-system","name":"جهاز الدوران","meaning":"القلب والدم والأوعية التي تتعاون لنقل المواد في الجسم.","example":"يدفع القلب الدم في الأوعية الدموية.","page":111,"aliases":["الجهاز الدوري"],"visualId":"circulatory-system","unit":"health","lesson":"systems","audioText":"جهاز الدوران. القلب والدم والأوعية التي تتعاون لنقل المواد في الجسم. مثال. يدفع القلب الدم في الأوعية الدموية.","imageQuiz":false},{"id":"heart","name":"القلب","meaning":"عضو عضلي يضخ الدم إلى الرئتين وإلى أجزاء الجسم.","example":"يزداد نبض القلب أثناء الجري.","page":111,"aliases":[],"visualId":"heart","unit":"health","lesson":"systems","audioText":"القلب. عضو عضلي يضخ الدم إلى الرئتين وإلى أجزاء الجسم. مثال. يزداد نبض القلب أثناء الجري.","imageQuiz":true},{"id":"atrium","name":"الأذين","meaning":"إحدى الحجرتين العلويتين في القلب، وتستقبل الدم العائد إليه.","example":"يستقبل الأذين الأيمن دمًا عائدًا من الجسم.","page":111,"aliases":[],"visualId":"atrium","unit":"health","lesson":"systems","audioText":"الأذين. إحدى الحجرتين العلويتين في القلب، وتستقبل الدم العائد إليه. مثال. يستقبل الأذين الأيمن دمًا عائدًا من الجسم.","imageQuiz":true},{"id":"ventricle","name":"البطين","meaning":"إحدى الحجرتين السفليتين في القلب، وتضخ الدم خارج القلب.","example":"يضخ البطين الأيسر الدم إلى الجسم.","page":111,"aliases":[],"visualId":"ventricle","unit":"health","lesson":"systems","audioText":"البطين. إحدى الحجرتين السفليتين في القلب، وتضخ الدم خارج القلب. مثال. يضخ البطين الأيسر الدم إلى الجسم.","imageQuiz":true},{"id":"artery","name":"الشريان","meaning":"وعاء دموي ينقل الدم بعيدًا عن القلب.","example":"تنقل الشرايين الدم الخارج من القلب.","page":111,"aliases":["الشرايين"],"visualId":"artery","unit":"health","lesson":"systems","audioText":"الشريان. وعاء دموي ينقل الدم بعيدًا عن القلب. مثال. تنقل الشرايين الدم الخارج من القلب.","imageQuiz":true},{"id":"vein","name":"الوريد","meaning":"وعاء دموي يعيد الدم إلى القلب.","example":"تعود الأوعية الوريدية بالدم إلى القلب.","page":111,"aliases":["الأوردة"],"visualId":"vein","unit":"health","lesson":"systems","audioText":"الوريد. وعاء دموي يعيد الدم إلى القلب. مثال. تعود الأوعية الوريدية بالدم إلى القلب.","imageQuiz":true},{"id":"capillary","name":"الشعيرات الدموية","meaning":"أوعية دقيقة جدًا يتم عبر جدرانها تبادل المواد مع الخلايا.","example":"تصل المغذيات إلى الخلايا عبر الشعيرات.","page":112,"aliases":["الشعرات الدموية"],"visualId":"capillary","unit":"health","lesson":"systems","audioText":"الشعيرات الدموية. أوعية دقيقة جدًا يتم عبر جدرانها تبادل المواد مع الخلايا. مثال. تصل المغذيات إلى الخلايا عبر الشعيرات.","imageQuiz":true},{"id":"oxygenated-blood","name":"الدم المؤكسج","meaning":"دم محمّل بكمية أكبر من الأكسجين بعد مروره بالرئتين.","example":"يعود الدم المؤكسج من الرئتين إلى القلب.","page":112,"aliases":[],"visualId":"oxygenated-blood","unit":"health","lesson":"systems","audioText":"الدم المؤكسج. دم محمّل بكمية أكبر من الأكسجين بعد مروره بالرئتين. مثال. يعود الدم المؤكسج من الرئتين إلى القلب.","imageQuiz":false},{"id":"deoxygenated-blood","name":"الدم غير المؤكسج","meaning":"دم أقل احتواءً على الأكسجين بعد أن أعطى الخلايا جزءًا منه.","example":"يضخ القلب هذا الدم إلى الرئتين ليحمل الأكسجين من جديد.","page":112,"aliases":[],"visualId":"deoxygenated-blood","unit":"health","lesson":"systems","audioText":"الدم غير المؤكسج. دم أقل احتواءً على الأكسجين بعد أن أعطى الخلايا جزءًا منه. مثال. يضخ القلب هذا الدم إلى الرئتين ليحمل الأكسجين من جديد.","imageQuiz":false},{"id":"respiration","name":"التنفس الخلوي","meaning":"عملية تطلق فيها الخلايا طاقة من الغذاء، ويستعمل كثير منها الأكسجين.","example":"تستخدم خلايا الجسم طاقة الغذاء للقيام بوظائفها.","page":110,"aliases":[],"visualId":"cell-respiration","unit":"health","lesson":"systems","audioText":"التنفس الخلوي. عملية تطلق فيها الخلايا طاقة من الغذاء، ويستعمل كثير منها الأكسجين. مثال. تستخدم خلايا الجسم طاقة الغذاء للقيام بوظائفها.","imageQuiz":true},{"id":"nutrient","name":"المادة الغذائية","meaning":"مادة في الطعام يحتاج إليها الجسم للنمو أو الطاقة أو المحافظة على وظائفه.","example":"يحتاج الجسم إلى مواد غذائية متنوعة.","page":116,"aliases":["المواد الغذائية"],"visualId":"nutrient","unit":"health","lesson":"nutrition","audioText":"المادة الغذائية. مادة في الطعام يحتاج إليها الجسم للنمو أو الطاقة أو المحافظة على وظائفه. مثال. يحتاج الجسم إلى مواد غذائية متنوعة.","imageQuiz":false},{"id":"carbohydrate","name":"الكربوهيدرات","meaning":"مواد غذائية تمد الجسم بالطاقة، ومنها السكريات والنشويات.","example":"الخبز والأرز من مصادر الكربوهيدرات.","page":116,"aliases":[],"visualId":"carbohydrate","unit":"health","lesson":"nutrition","audioText":"الكربوهيدرات. مواد غذائية تمد الجسم بالطاقة، ومنها السكريات والنشويات. مثال. الخبز والأرز من مصادر الكربوهيدرات.","imageQuiz":false},{"id":"starch-food","name":"النشويات","meaning":"نوع من الكربوهيدرات يوجد في أغذية مثل الأرز والخبز والبطاطا.","example":"تحتوي البطاطا على نشويات.","page":116,"aliases":[],"visualId":"starch","unit":"health","lesson":"nutrition","audioText":"النشويات. نوع من الكربوهيدرات يوجد في أغذية مثل الأرز والخبز والبطاطا. مثال. تحتوي البطاطا على نشويات.","imageQuiz":false},{"id":"sugar-food","name":"السكريات","meaning":"نوع من الكربوهيدرات تستفيد منه الخلايا في الحصول على الطاقة.","example":"تحتوي الفواكه على سكريات طبيعية.","page":116,"aliases":[],"visualId":"sugar-food","unit":"health","lesson":"nutrition","audioText":"السكريات. نوع من الكربوهيدرات تستفيد منه الخلايا في الحصول على الطاقة. مثال. تحتوي الفواكه على سكريات طبيعية.","imageQuiz":false},{"id":"vitamin","name":"الفيتامينات","meaning":"مواد يحتاج الجسم إلى كميات قليلة منها للمحافظة على وظائفه ونموه.","example":"تحتوي الفواكه والخضراوات على فيتامينات.","page":116,"aliases":[],"visualId":"vitamin","unit":"health","lesson":"nutrition","audioText":"الفيتامينات. مواد يحتاج الجسم إلى كميات قليلة منها للمحافظة على وظائفه ونموه. مثال. تحتوي الفواكه والخضراوات على فيتامينات.","imageQuiz":false},{"id":"vitamin-a","name":"فيتامين أ","meaning":"فيتامين مهم لوظائف منها الإبصار وصحة الجلد.","example":"الجزر من الأغذية التي تمد الجسم بمادة تتحول إلى فيتامين أ.","page":116,"aliases":["فيتامين A"],"visualId":"vitamin-a","unit":"health","lesson":"nutrition","audioText":"فيتامين أ. فيتامين مهم لوظائف منها الإبصار وصحة الجلد. مثال. الجزر من الأغذية التي تمد الجسم بمادة تتحول إلى فيتامين أ.","imageQuiz":false},{"id":"vitamin-c","name":"فيتامين ج","meaning":"فيتامين يسهم في سلامة أنسجة الجسم ووظائفه.","example":"البرتقال والفراولة من مصادر فيتامين ج.","page":116,"aliases":["فيتامين C"],"visualId":"vitamin-c","unit":"health","lesson":"nutrition","audioText":"فيتامين ج. فيتامين يسهم في سلامة أنسجة الجسم ووظائفه. مثال. البرتقال والفراولة من مصادر فيتامين ج.","imageQuiz":false},{"id":"vitamin-d","name":"فيتامين د","meaning":"فيتامين يساعد الجسم على الاستفادة من الكالسيوم لصحة العظام.","example":"توجد مصادر لفيتامين د في الأسماك وبعض الأغذية المدعمة.","page":116,"aliases":["فيتامين D"],"visualId":"vitamin-d","unit":"health","lesson":"nutrition","audioText":"فيتامين د. فيتامين يساعد الجسم على الاستفادة من الكالسيوم لصحة العظام. مثال. توجد مصادر لفيتامين د في الأسماك وبعض الأغذية المدعمة.","imageQuiz":false},{"id":"mineral","name":"الأملاح المعدنية","meaning":"عناصر يحتاجها الجسم بكميات مناسبة لأداء وظائفه.","example":"الكالسيوم والحديد من المعادن المهمة للجسم.","page":117,"aliases":["المعادن","المواد المعدنية"],"visualId":"mineral","unit":"health","lesson":"nutrition","audioText":"الأملاح المعدنية. عناصر يحتاجها الجسم بكميات مناسبة لأداء وظائفه. مثال. الكالسيوم والحديد من المعادن المهمة للجسم.","imageQuiz":false},{"id":"calcium","name":"الكالسيوم","meaning":"عنصر معدني مهم لبناء العظام والأسنان ووظائف أخرى.","example":"الحليب من مصادر الكالسيوم.","page":117,"aliases":[],"visualId":"calcium","unit":"health","lesson":"nutrition","audioText":"الكالسيوم. عنصر معدني مهم لبناء العظام والأسنان ووظائف أخرى. مثال. الحليب من مصادر الكالسيوم.","imageQuiz":false},{"id":"iron-nutrient","name":"الحديد","meaning":"عنصر معدني يدخل في مادة تساعد الدم على نقل الأكسجين.","example":"تحتوي بعض الأغذية على الحديد الذي يحتاجه الجسم.","page":117,"aliases":[],"visualId":"iron-nutrient","unit":"health","lesson":"nutrition","audioText":"الحديد. عنصر معدني يدخل في مادة تساعد الدم على نقل الأكسجين. مثال. تحتوي بعض الأغذية على الحديد الذي يحتاجه الجسم.","imageQuiz":false},{"id":"fat","name":"الدهون","meaning":"مواد غذائية تخزن الطاقة وتدخل في بناء الخلايا وتساعد في وظائف الجسم.","example":"المكسرات والزيوت من مصادر الدهون.","page":117,"aliases":[],"visualId":"fat","unit":"health","lesson":"nutrition","audioText":"الدهون. مواد غذائية تخزن الطاقة وتدخل في بناء الخلايا وتساعد في وظائف الجسم. مثال. المكسرات والزيوت من مصادر الدهون.","imageQuiz":false},{"id":"protein","name":"البروتينات","meaning":"مواد تدخل في بناء أنسجة الجسم ونموها وإصلاحها.","example":"البيض والأسماك والبقول من مصادر البروتينات.","page":118,"aliases":[],"visualId":"protein","unit":"health","lesson":"nutrition","audioText":"البروتينات. مواد تدخل في بناء أنسجة الجسم ونموها وإصلاحها. مثال. البيض والأسماك والبقول من مصادر البروتينات.","imageQuiz":false},{"id":"water-nutrient","name":"الماء","meaning":"مادة يحتاجها الجسم لنقل المواد وتنظيم الحرارة وأداء وظائفه.","example":"يساعد الماء الجسم على التخلص من الفضلات.","page":118,"aliases":[],"visualId":"water-nutrient","unit":"health","lesson":"nutrition","audioText":"الماء. مادة يحتاجها الجسم لنقل المواد وتنظيم الحرارة وأداء وظائفه. مثال. يساعد الماء الجسم على التخلص من الفضلات.","imageQuiz":false},{"id":"balanced-diet","name":"الغذاء المتوازن","meaning":"غذاء متنوع يمد الجسم بحاجاته بكميات مناسبة.","example":"تجمع الوجبة المتوازنة بين أصناف غذائية متنوعة.","page":118,"aliases":[],"visualId":"balanced-diet","unit":"health","lesson":"nutrition","audioText":"الغذاء المتوازن. غذاء متنوع يمد الجسم بحاجاته بكميات مناسبة. مثال. تجمع الوجبة المتوازنة بين أصناف غذائية متنوعة.","imageQuiz":false},{"id":"immune-system","name":"جهاز المناعة","meaning":"أجزاء وخلايا تتعاون للدفاع عن الجسم ضد مسببات الأمراض.","example":"يساعد الغذاء المتوازن على سلامة وظائف الجسم.","page":118,"aliases":[],"visualId":"immune-system","unit":"health","lesson":"nutrition","audioText":"جهاز المناعة. أجزاء وخلايا تتعاون للدفاع عن الجسم ضد مسببات الأمراض. مثال. يساعد الغذاء المتوازن على سلامة وظائف الجسم.","imageQuiz":false},{"id":"pathogen","name":"مسبب المرض","meaning":"عامل يستطيع إحداث مرض، مثل بعض أنواع البكتيريا والفيروسات.","example":"تسبب بعض الفيروسات أمراضًا تنفسية.","page":119,"aliases":["مسببات الأمراض"],"visualId":"pathogen","unit":"health","lesson":"nutrition","audioText":"مسبب المرض. عامل يستطيع إحداث مرض، مثل بعض أنواع البكتيريا والفيروسات. مثال. تسبب بعض الفيروسات أمراضًا تنفسية.","imageQuiz":false},{"id":"virus-health","name":"الفيروسات","meaning":"عوامل دقيقة لا تتكاثر إلا داخل خلايا حية، وقد يسبب بعضها أمراضًا.","example":"يسبب فيروس الإنفلونزا مرضًا تنفسيًا.","page":119,"aliases":[],"visualId":"virus","unit":"health","lesson":"nutrition","audioText":"الفيروسات. عوامل دقيقة لا تتكاثر إلا داخل خلايا حية، وقد يسبب بعضها أمراضًا. مثال. يسبب فيروس الإنفلونزا مرضًا تنفسيًا.","imageQuiz":true},{"id":"bacteria-health","name":"البكتيريا","meaning":"مخلوقات حية وحيدة الخلية، منها المفيد ومنها ما قد يسبب أمراضًا.","example":"يساعد بعض أنواع البكتيريا في هضم الطعام.","page":119,"aliases":[],"visualId":"bacteria","unit":"health","lesson":"nutrition","audioText":"البكتيريا. مخلوقات حية وحيدة الخلية، منها المفيد ومنها ما قد يسبب أمراضًا. مثال. يساعد بعض أنواع البكتيريا في هضم الطعام.","imageQuiz":true},{"id":"prevention","name":"الوقاية","meaning":"اتباع سلوكيات تقلل احتمال الإصابة بالأمراض.","example":"يسهم غسل اليدين في تقليل انتقال الجراثيم.","page":120,"aliases":[],"visualId":"prevention","unit":"health","lesson":"nutrition","audioText":"الوقاية. اتباع سلوكيات تقلل احتمال الإصابة بالأمراض. مثال. يسهم غسل اليدين في تقليل انتقال الجراثيم.","imageQuiz":true},{"id":"vaccine","name":"التطعيم","meaning":"وسيلة تساعد جهاز المناعة على التعرف إلى مسبب مرض محدد والاستعداد لمقاومته.","example":"تؤخذ التطعيمات وفق إرشادات الجهات الصحية.","page":120,"aliases":["اللقاح","التطعيمات"],"visualId":"vaccine","unit":"health","lesson":"nutrition","audioText":"التطعيم. وسيلة تساعد جهاز المناعة على التعرف إلى مسبب مرض محدد والاستعداد لمقاومته. مثال. تؤخذ التطعيمات وفق إرشادات الجهات الصحية.","imageQuiz":true}]};